		public static List<CheckResult> RunShellBagCheck()
		{
			List<CheckResult> list = new List<CheckResult>();
			List<string> list2 = new List<string>();
			List<string> list3 = new List<string>();
			List<string> list4 = new List<string>();
			string[] array = new string[3] { "Software\\Microsoft\\Windows\\Shell\\BagMRU", "Software\\Microsoft\\Windows\\ShellNoRoam\\BagMRU", "Software\\Classes\\Local Settings\\Software\\Microsoft\\Windows\\Shell\\BagMRU" };
			string[] array2 = array;
			foreach (string name in array2)
			{
				try
				{
					using (RegistryKey registryKey = Registry.CurrentUser.OpenSubKey(name, false))
					{
						if (registryKey != null)
						{
							CollectBagPaths(registryKey, list2, 0);
						}
					}
				}
				catch
				{
				}
			}
			try
			{
				using (RegistryKey registryKey2 = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\Shell\\BagMRU", false))
				{
					if (registryKey2 != null)
					{
						int subKeyCount = registryKey2.SubKeyCount;
						int valueCount = registryKey2.ValueCount;
						TimeSpan uptime = TimeSpan.FromMilliseconds(Environment.TickCount);
						// Empty root BagMRU is standard on modern Windows (Local Settings is used instead)
					}
				}
			}
			catch
			{
			}
			foreach (string item in list2)
			{
				string text = item.ToLowerInvariant();
				if (CheatDatabases.IsWhitelistedPath(text))
				{
					continue;
				}
				bool isCleaner = false;
				foreach (string cl in CheatDatabases.KnownCleanerSignatures)
				{
					if (cl.Length >= 4 && text.Contains(cl))
					{
						list4.Add("🚨 [5.08 - Папка клинера в ShellBag]: [" + cl + "] " + item);
						isCleaner = true;
						break;
					}
				}
				if (isCleaner) continue;

				string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
				foreach (string text2 in extraCheatClients)
				{
					if (text2.Length >= 4 && text.Contains(text2.ToLowerInvariant()))
					{
						if (!Directory.Exists(item))
						{
							list4.Add("🗑️ [5.08 - Удалённая папка чита из ShellBag]: [" + text2 + "] " + item);
						}
						else
						{
							list4.Add("🚨 [5.01 - Папка чита в ShellBag]: [" + text2 + "] " + item);
						}
						break;
					}
				}
			}
			try
			{
				string[] array3 = new string[3]
				{
					Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "ShellBag backups"),
					Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Documents", "ShellBag backups"),
					Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop), "ShellBag backups")
				};
				string[] array4 = array3;
				foreach (string path in array4)
				{
					if (!Directory.Exists(path))
					{
						continue;
					}
					foreach (string item2 in Directory.GetFiles(path, "*", SearchOption.AllDirectories).Take(50))
					{
						list3.Add("Бэкап ShellBag: " + item2 + " | изменён: " + SafeWriteTime(item2).ToString("dd.MM.yyyy HH:mm"));
					}
				}
			}
			catch
			{
			}
			List<string> list5 = new List<string>();
			list5.AddRange(list4.Distinct().Take(40));
			list5.AddRange(list3.Take(20));
			CheckResult checkResult = Make("История", "ShellBag: посещённые папки читов", list5, CheckSeverity.Critical, "Следов чит-папок в ShellBag нет");
			checkResult.Detected = list5.Count > 0;
			list.Add(checkResult);
			return list;
		}

		private static void CollectBagPaths(RegistryKey key, List<string> sink, int depth)
		{
			if (depth > 6 || sink.Count > 400)
			{
				return;
			}
			try
			{
				string[] valueNames = key.GetValueNames();
				foreach (string name in valueNames)
				{
					byte[] array = key.GetValue(name) as byte[];
					if (array != null && array.Length >= 8)
					{
						string text = DecodeShellItem(array);
						if (!string.IsNullOrEmpty(text))
						{
							sink.Add(text);
						}
					}
				}
				string[] subKeyNames = key.GetSubKeyNames();
				foreach (string name2 in subKeyNames)
				{
					using (RegistryKey registryKey = key.OpenSubKey(name2, false))
					{
						if (registryKey != null)
						{
							CollectBagPaths(registryKey, sink, depth + 1);
						}
					}
				}
			}
			catch
			{
			}
		}

		private static string DecodeShellItem(byte[] raw)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i + 1 < raw.Length; i += 2)
			{
				char c = (char)(raw[i] | (raw[i + 1] << 8));
				if (c >= ' ' && c < '\u2000')
				{
					stringBuilder.Append(c);
				}
				else
				{
					stringBuilder.Append(' ');
				}
			}
			string text = stringBuilder.ToString();
			int num = text.IndexOf(":\\", StringComparison.Ordinal);
			if (num < 1)
			{
				num = text.IndexOf("\\\\", StringComparison.Ordinal);
			}
			if (num < 0)
			{
				return null;
			}
			string text2 = text.Substring(Math.Max(0, num - 1)).Trim();
			string text3 = text2;
			char[] separator = new char[1];
			text2 = text3.Split(separator)[0];
			if (text2.Length < 4)
			{
				return null;
			}
			if (text2.Length <= 260)
			{
				return text2;
			}
			return text2.Substring(0, 260);
		}

		public static List<CheckResult> RunEverythingConfigCheck()
		{
			List<string> list = new List<string>();
			try
			{
				string[] array = new string[2]
				{
					Path.Combine(AppData(), "Everything", "Everything.ini"),
					Path.Combine(AppData(), "Everything", "Everything.db")
				};
				string path = array[0];
				if (File.Exists(path))
				{
					string[] array2 = File.ReadAllLines(path);
					bool flag = false;
					bool flag2 = false;
					string[] array3 = array2;
					foreach (string text in array3)
					{
						string text2 = text.Trim().ToLowerInvariant();
						if (text2.StartsWith("exclude_list") || text2.StartsWith("excludefolder") || text2.StartsWith("excludefile"))
						{
							int num = text2.IndexOf('=');
							string text3 = ((num >= 0) ? text2.Substring(num + 1).Trim() : "");
							if (text3.Length > 0 && text3 != "1" && text3 != "0" && text3 != "true")
							{
								flag = true;
								list.Add("Everything: настроены исключения → " + text.Trim());
							}
						}
						if (text2.StartsWith("local_only") && text2.Contains("=1"))
						{
							flag2 = true;
						}
					}
					if (flag)
					{
						list.Add("Everything: папки/файлы исключены из индекса — по методичке требуется убрать все исключения");
					}
					if (flag2)
					{
						list.Add("Everything: включён режим Local only — индекс неполный");
					}
				}
				else
				{
					list.Add("Everything.ini не найден (программа не установлена или портативная версия)");
				}
			}
			catch
			{
			}
			try
			{
				string path2 = Path.Combine(AppData(), "Everything", "Search History.csv");
				if (File.Exists(path2))
				{
					string[] source = File.ReadAllLines(path2);
					foreach (string item in source.Take(200))
					{
						string text4 = item.ToLowerInvariant();
						string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
						foreach (string text5 in extraCheatClients)
						{
							if (text4.Contains(text5.ToLowerInvariant()))
							{
								list.Add("Everything: поиск чита [" + text5 + "] → " + item.Trim());
								break;
							}
						}
					}
				}
			}
			catch
			{
			}
			List<string> found = list.Where((string f) => !f.Contains("не найден")).ToList();
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("История", "Everything: настройки индексации и история поиска (методичка SS)", found, CheckSeverity.Warning, "Everything: исключений нет, подозрительных запросов не найдено"));
			return list2;
		}

		public static List<CheckResult> RunRequiredServicesCheck()
		{
			string[] array = new string[] { "PcaSvc", "SysMain", "DPS", "EventLog", "DcomLaunch", "CDPSvc", "DiagTrack", "Dusmsvc", "bam", "AppInfo" };
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			string[] array2 = array;
			foreach (string text in array2)
			{
				try
				{
					using (RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SYSTEM\\CurrentControlSet\\Services\\" + text, false))
					{
						if (registryKey == null)
						{
							list.Add("❌ " + text + ": служба НЕ НАЙДЕНА в системе");
							continue;
						}
						object value = registryKey.GetValue("Start");
						int num = ((value == null) ? (-1) : Convert.ToInt32(value));
						if (num == 4)
						{
							list.Add("❌ " + text + ": ОТКЛЮЧЕНА (Start=4)");
							continue;
						}
						list2.Add("✅ " + text + ": активна (Start=" + num + ")");
					}
				}
				catch
				{
				}
			}
			List<string> list3 = new List<string>();
			list3.AddRange(list);
			list3.AddRange(list2);
			CheckResult checkResult = Make("Следы запуска", "Обязательные службы Windows (PcaSvc/DPS/BAM/EventLog/CDPSvc...)", list, CheckSeverity.Critical, "Все обязательные службы включены");
			checkResult.Evidence = string.Join("\r\n", list3.ToArray());
			List<CheckResult> list4 = new List<CheckResult>();
			list4.Add(checkResult);
			return list4;
		}

		public static List<CheckResult> RunPrefetchProcessCheck()
		{
			List<string> list = new List<string>();
			string path = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "Prefetch");
			if (!Directory.Exists(path))
			{
				List<CheckResult> list2 = new List<CheckResult>();
				list2.Add(Make("Следы запуска", "Prefetch: запуск софтов, cmd / consent / javaw (SS методичка)", list, CheckSeverity.Info, "Папка Prefetch недоступна (нужны права администратора)"));
				return list2;
			}
			string[] array = new string[4] { "cmd.exe", "conhost.exe", "consent.exe", "javaw.exe" };
			try
			{
				string[] files = Directory.GetFiles(path, "*.pf");
				string[] array2 = files;
				foreach (string path2 in array2)
				{
					string text = Path.GetFileName(path2).ToUpperInvariant();
					DateTime dateTime = SafeWriteTime(path2);
					if ((DateTime.Now - dateTime).TotalHours > 48.0)
					{
						continue;
					}
					bool flag = false;
