		private static void InspectXrayZip(string zipPath, List<string> sink)
		{
			try
			{
				using (ZipArchive zipArchive = ZipFile.OpenRead(zipPath))
				{
					foreach (ZipArchiveEntry entry in zipArchive.Entries)
					{
						string text = entry.FullName.Replace('\\', '/').ToLowerInvariant();
						if (!text.EndsWith("/stone.png"))
						{
							continue;
						}
						try
						{
							using (Stream stream = entry.Open())
							{
								using (Bitmap bmp = new Bitmap(stream))
								{
									if (IsMostlyTransparent(bmp))
									{
										sink.Add("X-Ray ресурспак: " + zipPath + " — stone.png прозрачный");
									}
								}
							}
						}
						catch
						{
						}
					}
				}
			}
			catch
			{
			}
		}

		private static bool IsTransparentImage(string path)
		{
			try
			{
				using (Bitmap bmp = new Bitmap(path))
				{
					return IsMostlyTransparent(bmp);
				}
			}
			catch
			{
				return false;
			}
		}

		private static bool IsMostlyTransparent(Bitmap bmp)
		{
			int num = 0;
			int num2 = 0;
			int num3 = Math.Max(1, bmp.Width / 16);
			int num4 = Math.Max(1, bmp.Height / 16);
			for (int i = 0; i < bmp.Height; i += num4)
			{
				for (int j = 0; j < bmp.Width; j += num3)
				{
					num2++;
					if (bmp.GetPixel(j, i).A < 60)
					{
						num++;
					}
				}
			}
			if (num2 > 0)
			{
				return num * 100 / num2 >= 40;
			}
			return false;
		}

		private static bool ZipContainsEntry(string zipPath, string entryPrefix)
		{
			try
			{
				using (ZipArchive zipArchive = ZipFile.OpenRead(zipPath))
				{
					foreach (ZipArchiveEntry entry in zipArchive.Entries)
					{
						string text = entry.FullName.Replace('\\', '/').ToLowerInvariant();
						if (text.StartsWith(entryPrefix.ToLowerInvariant()))
						{
							return true;
						}
					}
				}
			}
			catch
			{
			}
			return false;
		}

