		public static List<CheckResult> RunRecycleBinAgeCheck()
		{
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			List<string> list3 = new List<string>();
			DriveInfo[] array;
			try
			{
				array = DriveInfo.GetDrives();
			}
			catch
			{
				array = new DriveInfo[0];
			}
			DriveInfo[] array2 = array;
			foreach (DriveInfo driveInfo in array2)
			{
				try
				{
					if (!driveInfo.IsReady || (driveInfo.DriveType != DriveType.Fixed && driveInfo.DriveType != DriveType.Removable))
					{
						continue;
					}
					string path = Path.Combine(driveInfo.RootDirectory.FullName, "$Recycle.Bin");
					if (!Directory.Exists(path))
					{
						continue;
					}
					DateTime lastWriteTime = Directory.GetLastWriteTime(path);
					double totalMinutes = (DateTime.Now - lastWriteTime).TotalMinutes;
					string text = driveInfo.Name + " — изменена " + lastWriteTime.ToString("dd.MM.yyyy HH:mm") + " (" + Math.Round(totalMinutes, 0) + " мин назад)";
					if (totalMinutes >= 0.0 && totalMinutes <= 60.0)
					{
						list.Add("Корзина " + text + " → очищалась/менялась перед проверкой");
					}
					else
					{
						list3.Add(text);
					}
					try
					{
						string[] files = Directory.GetFiles(path, "*", SearchOption.AllDirectories);
						string[] array3 = files;
						foreach (string text2 in array3)
						{
							string text3 = Path.GetFileName(text2).ToLowerInvariant();
							if (!text3.EndsWith(".jar") && !text3.EndsWith(".dll") && !text3.EndsWith(".exe") && !text3.EndsWith(".bat"))
							{
								continue;
							}
							FileInfo fileInfo = new FileInfo(text2);
							bool flag = CheatDatabases.KnownCheatJarSizes.Contains(fileInfo.Length);
							bool flag2 = false;
							string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
							foreach (string text4 in extraCheatClients)
							{
								if (text4.Length >= 4 && text3.Contains(text4.ToLowerInvariant()))
								{
									flag2 = true;
									break;
								}
							}
							if (flag || flag2 || (DateTime.Now - fileInfo.LastWriteTime).TotalHours <= 24.0)
							{
								list2.Add(string.Format("\ud83d\uddd1\ufe0f Удалённый объект в корзине: {0} ({1:N0} байт, {2:dd.MM.yyyy HH:mm}){3}", Path.GetFileName(text2), fileInfo.Length, fileInfo.LastWriteTime, flag ? " [ЭТАЛОННЫЙ РАЗМЕР ЧИТА ИЗ БАЗЫ!]" : (flag2 ? " [ИМЯ ЧИТА!]" : "")));
							}
						}
					}
					catch
					{
					}
				}
				catch
				{
				}
			}
			List<string> list4 = new List<string>();
			list4.AddRange(list2);
			list4.AddRange(list);
			CheckSeverity severity = ((list2.Count > 0) ? CheckSeverity.Critical : ((list.Count > 0) ? CheckSeverity.NeedsCheck : CheckSeverity.Info));
			string cleanText = ((list2.Count > 0) ? ("Найдено удалённых подозрительных файлов в корзине: " + list2.Count) : ((list.Count > 0) ? "Корзина менялась/очищалась за последний час!" : "Корзина не менялась в последний час"));
			CheckResult checkResult = Make("История", "Корзина $Recycle.Bin на всех дисках (свежие изменения и файлы)", list4, severity, cleanText);
			if (list4.Count == 0)
			{
				checkResult.Evidence = string.Join("\r\n", list3.ToArray());
			}
			List<CheckResult> list5 = new List<CheckResult>();
			list5.Add(checkResult);
			return list5;
		}

