		public static List<CheckResult> RunUsnJournalCheck()
		{
			List<string> list = new List<string>();
			string[] eventLogs = new string[] { "Application", "System" };
			foreach (string logName in eventLogs)
			{
				try
				{
					using (EventLog eventLog = new EventLog(logName))
					{
						int count = eventLog.Entries.Count;
						int num = count - 1;
						while (num >= 0 && num >= count - 500)
						{
							EventLogEntry entry = eventLog.Entries[num];
							if (entry.InstanceId == 3079 || entry.InstanceId == 3080)
							{
								string text = entry.Message ?? "";
								string tool = text.ToLowerInvariant().Contains("fsutil") ? " через FSUTIL.EXE" : "";
								list.Add(string.Format("🚨 [5.08 - Очистка журнала USN] EventID {0} ({1:dd.MM.yyyy HH:mm:ss}) в логе {2}: журнал USN очищен/удалён{3}", entry.InstanceId, entry.TimeGenerated, logName, tool));
							}
							num--;
						}
					}
				}
				catch { }
			}

			try
			{
				string path = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "Prefetch");
				if (Directory.Exists(path))
				{
					string[] usnWipers = new string[] { "FSUTIL*.pf", "WEVTUTIL*.pf", "CIPHER*.pf", "SDELETE*.pf", "JOURNALTRACE*.pf", "KOID*.pf", "USNJRNL*.pf", "USN*.pf", "VANISH*.pf", "BCWIPER*.pf", "CLEANER*.pf" };
					HashSet<string> seenPf = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
					foreach (string pattern in usnWipers)
					{
						string[] files = Directory.GetFiles(path, pattern);
						foreach (string path2 in files)
						{
							if (!seenPf.Add(path2)) continue;
							list.Add(string.Format("🚨 [5.08 - Запуск утилиты очистки журнала USN] В Prefetch обнаружен запуск: {0} ({1:dd.MM.yyyy HH:mm:ss})", Path.GetFileName(path2), SafeWriteTime(path2)));
						}
					}
				}
			}
			catch
			{
			}
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Следы запуска", "Очистка USN Journal (EventID 3079/3080 / FSUTIL.EXE / Wipers)", list, CheckSeverity.Critical, "Журнал USN не очищался, утилит очистки USN не запускалось"));
			return list2;
		}

