							{
								list.Add(string.Format("[{0}] {1}", eventRecord.TimeCreated.HasValue ? eventRecord.TimeCreated.Value.ToString("dd.MM.yyyy HH:mm") : "—", (text.Length > 160) ? (text.Substring(0, 160) + "...") : text));
							}
							num++;
						}
					}
				}
			}
			catch
			{
			}
			CheckResult item = Make("История", "Инвентарь программ (Program-Inventory / методичка мануалов)", list, CheckSeverity.Info, "Журнал Program-Inventory: запусков сторонних ядер Java не зафиксировано");
