		public static List<CheckResult> RunFirewallAppHistoryCheck()
		{
			List<string> list = new List<string>();
			try
			{
				using (RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SYSTEM\\CurrentControlSet\\Services\\SharedAccess\\Parameters\\FirewallPolicy\\FirewallRules", false))
				{
					if (registryKey != null)
					{
						string[] valueNames = registryKey.GetValueNames();
						foreach (string name in valueNames)
						{
							string text = Convert.ToString(registryKey.GetValue(name));
							if (string.IsNullOrEmpty(text))
							{
								continue;
							}
							string text2 = text.ToLowerInvariant();
							if (!text2.Contains("app="))
							{
								continue;
							}
							int num = text2.IndexOf("app=");
							int num2 = text2.IndexOf('|', num);
							string text3 = ((num2 > num) ? text.Substring(num + 4, num2 - (num + 4)) : text.Substring(num + 4));
							text3 = text3.Trim();
							string text4 = text3.ToLowerInvariant();
							bool flag = text4.EndsWith("javaw.exe") || text4.EndsWith("java.exe");
							bool flag2 = false;
							string arg = "";
