									arg = text5;
									break;
								}
							}
							if (flag2)
							{
								bool flag3 = File.Exists(text3);
								list.Add(string.Format("\ud83d\udea8 ЧИТ В ПРАВИЛАХ БРАНДМАУЭРА [{0}]: {1} ({2})", arg, text3, flag3 ? "Файл существует" : "ФАЙЛ УДАЛЁН С ДИСКА!"));
							}
							else if (flag && (text4.Contains("\\temp\\") || text4.Contains("\\downloads\\") || text4.Contains("\\desktop\\")))
							{
								bool flag4 = File.Exists(text3);
								list.Add(string.Format("⚠\ufe0f JAVAW ИЗ НЕТИПИЧНОЙ ПАПКИ: {0} ({1})", text3, flag4 ? "Файл существует" : "ФАЙЛ УДАЛЁН!"));
							}
						}
					}
				}
			}
			catch
			{
			}
			bool flag5 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Сеть и Интернет", "Сетевые правила брандмауэра для Java и чит-клиентов (Шаг 02)", list, (!flag5) ? CheckSeverity.Warning : CheckSeverity.Critical, "Подозрительных правил брандмауэра для Java/читов не обнаружено"));
			return list2;
		}

