		public static List<CheckResult> RunActivitiesCacheCheck()
		{
			List<string> list = new List<string>();
			try
			{
				string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
				string path = Path.Combine(folderPath, "ConnectedDevicesPlatform");
				if (Directory.Exists(path))
				{
					string[] files = Directory.GetFiles(path, "ActivitiesCache.db*", SearchOption.AllDirectories);
					string[] array = files;
					foreach (string text in array)
					{
						try
						{
							FileInfo fileInfo = new FileInfo(text);
							if (fileInfo.Length > 31457280)
							{
								continue;
							}
							byte[] array2;
							using (FileStream fileStream = new FileStream(text, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
							{
								long maxRead = 1048576L;
								long seekPos = Math.Max(0, fileInfo.Length - maxRead);
								int num = (int)(fileInfo.Length - seekPos);
								fileStream.Seek(seekPos, SeekOrigin.Begin);
								array2 = new byte[num];
								fileStream.Read(array2, 0, num);
							}
							string text2 = Encoding.ASCII.GetString(array2);
							string text3 = Encoding.Unicode.GetString(array2);
							string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
							foreach (string text4 in extraCheatClients)
							{
								if (text4.Length < 4 || CheatDatabases.IsAmbiguous(text4))
								{
									continue;
								}
								string value = "\\" + text4.ToLowerInvariant();
								string valueExe = text4.ToLowerInvariant() + ".exe";
								if (text2.IndexOf(value, StringComparison.OrdinalIgnoreCase) >= 0 || text3.IndexOf(value, StringComparison.OrdinalIgnoreCase) >= 0 ||
								    text2.IndexOf(valueExe, StringComparison.OrdinalIgnoreCase) >= 0 || text3.IndexOf(valueExe, StringComparison.OrdinalIgnoreCase) >= 0)
								{
									list.Add(string.Format("\ud83d\udea8 [ActivitiesCache.db] Активность/запуск софта [{0}] в Windows Timeline: {1}", text4, text));
									if (list.Count >= 20)
									{
										break;
									}
								}
							}
							CheatDatabases.BanRule[] bannedByRegulation = CheatDatabases.BannedByRegulation;
							foreach (CheatDatabases.BanRule banRule in bannedByRegulation)
							{
								string[] keys = banRule.Keys;
								foreach (string text5 in keys)
								{
									if (text5.Length >= 4 && (text2.IndexOf(text5, StringComparison.OrdinalIgnoreCase) >= 0 || text3.IndexOf(text5, StringComparison.OrdinalIgnoreCase) >= 0))
									{
										list.Add(string.Format("\ud83d\udea8 [ActivitiesCache.db] Запрещённый пункт {0} ({1}) в Timeline: ключ '{2}'", banRule.Id, banRule.Title, text5));
										break;
									}
								}
								if (list.Count >= 20)
								{
									break;
								}
							}
							goto IL_01cd;
						}
						catch
						{
							goto IL_01cd;
						}
						IL_01cd:
						if (list.Count >= 20)
						{
							break;
						}
					}
				}
			}
			catch
			{
			}
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Windows Timeline (ActivitiesCache.db активность ПО)", list, (list.Count > 0) ? CheckSeverity.Critical : CheckSeverity.Info, "В базе Windows ActivitiesCache.db следов активности читов не обнаружено"));
			return list2;
		}

		public static List<CheckResult> RunJumpListsCheck()
		{
			List<string> list = new List<string>();
			HashSet<string> seenHits = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			try
			{
				string path = Path.Combine(AppData(), "Microsoft", "Windows", "Recent");
				string[] array = new string[2]
				{
					Path.Combine(path, "AutomaticDestinations"),
					Path.Combine(path, "CustomDestinations")
				};
				string[] array2 = array;
				foreach (string path2 in array2)
				{
					if (!Directory.Exists(path2))
					{
						continue;
					}
					string[] files = Directory.GetFiles(path2, "*.*destinations-ms");
					string[] array3 = files;
					foreach (string text in array3)
					{
						try
						{
							FileInfo fileInfo = new FileInfo(text);
							if (fileInfo.Length > 20971520)
							{
								continue;
							}
							byte[] bytes = null;
							using (FileStream fs = new FileStream(text, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
							{
								int len = (int)Math.Min(fs.Length, 1048576L);
								bytes = new byte[len];
								int readTotal = 0;
								while (readTotal < len)
								{
									int r = fs.Read(bytes, readTotal, len - readTotal);
									if (r <= 0) break;
									readTotal += r;
								}
								if (readTotal < len) Array.Resize(ref bytes, readTotal);
							}
							if (bytes == null || bytes.Length < 16) continue;

							string text2 = Encoding.ASCII.GetString(bytes);
							string text3 = Encoding.Unicode.GetString(bytes);

							// Extract all file paths from JumpList stream
							MatchCollection mcAscii = Regex.Matches(text2, @"[a-zA-Z]:\\[^<>""/|?*\x00-\x1F\r\n\t]+?\.[a-zA-Z0-9]{2,5}");
							MatchCollection mcUnicode = Regex.Matches(text3, @"[a-zA-Z]:\\[^<>""/|?*\x00-\x1F\r\n\t]+?\.[a-zA-Z0-9]{2,5}");

							List<string> candidatePaths = new List<string>();
							foreach (Match m in mcAscii) candidatePaths.Add(m.Value.Trim());
							foreach (Match m in mcUnicode) candidatePaths.Add(m.Value.Trim());

							foreach (string cPath in candidatePaths)
							{
								if (cPath.Length < 5 || seenHits.Contains(cPath)) continue;
								string cPathLower = cPath.ToLowerInvariant();
								if (CheatDatabases.IsWhitelistedPath(cPathLower)) continue;

								bool isCheat = false;
								string matchedCheat = "";
								foreach (string cheat in CheatDatabases.ExtraCheatClients)
								{
									if (cheat.Length >= 4 && CheatDetector.MatchesCheatName(cPathLower, cheat))
									{
										isCheat = true;
										matchedCheat = cheat;
										break;
									}
								}
								if (!isCheat)
								{
									foreach (string cl in CheatDetector.CheatClientNames)
									{
										if (CheatDetector.MatchesCheatName(cPathLower, cl))
										{
											isCheat = true;
											matchedCheat = cl;
											break;
										}
									}
								}

								// Check cleaners
								bool isCleaner = false;
								string matchedCleaner = "";
								if (!isCheat)
								{
									foreach (string cleaner in CheatDatabases.KnownCleanerSignatures)
									{
										if (cPathLower.Contains(cleaner.ToLowerInvariant()))
										{
											isCleaner = true;
											matchedCleaner = cleaner;
											break;
										}
									}
								}

								bool exists = File.Exists(cPath);
								if (isCheat)
								{
									seenHits.Add(cPath);
									if (!exists)
									{
										list.Add(string.Format("🗑️ [5.08 - Удалённый чит из JumpLists] Чит [{0}]: {1} (AppId: {2}) [ФАЙЛ УДАЛЁН!]", matchedCheat, cPath, fileInfo.Name));
									}
									else
									{
										list.Add(string.Format("🔴 [5.01 - Чит в JumpLists] Чит [{0}]: {1} (AppId: {2})", matchedCheat, cPath, fileInfo.Name));
									}
								}
								else if (isCleaner)
								{
									seenHits.Add(cPath);
									list.Add(string.Format("🚨 [5.08 - Запуск клинера в JumpLists] Утилита очистки [{0}]: {1} (AppId: {2})", matchedCleaner, cPath, fileInfo.Name));
								}
								else if (!exists && (cPathLower.EndsWith(".exe") || cPathLower.EndsWith(".jar") || cPathLower.EndsWith(".dll")) &&
									(cPathLower.Contains("\\temp\\") || cPathLower.Contains("\\downloads\\") || cPathLower.Contains("\\desktop\\") || cPathLower.Contains("\\.minecraft\\")))
								{
									seenHits.Add(cPath);
									list.Add(string.Format("⚠️ [5.08 - Удалённый исполняемый файл из JumpLists] {0} (AppId: {1})", cPath, fileInfo.Name));
								}

								if (list.Count >= 30) break;
							}
						}
						catch
						{
						}
						if (list.Count >= 30) break;
					}
				}
			}
			catch
			{
			}
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Списки переходов JumpLists (Automatic & Custom Destinations)", list, (list.Count > 0) ? CheckSeverity.Critical : CheckSeverity.Info, "В JumpLists обращений к запрещённым файлам не зафиксировано"));
			return list2;
		}

		public static List<CheckResult> RunComDlg32MRUCheck()
		{
			List<string> list = new List<string>();
			HashSet<string> seenEntries = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			try
			{
				using (RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\ComDlg32\\OpenSavePidlMRU"))
				{
					if (registryKey != null)
					{
						string[] subKeyNames = registryKey.GetSubKeyNames();
						foreach (string text in subKeyNames)
						{
							using (RegistryKey registryKey2 = registryKey.OpenSubKey(text))
							{
								if (registryKey2 == null)
								{
									continue;
								}
								string[] valueNames = registryKey2.GetValueNames();
								foreach (string text2 in valueNames)
								{
									if (text2 == "MRUListEx")
									{
										continue;
									}
									byte[] array = registryKey2.GetValue(text2) as byte[];
									if (array == null || array.Length < 6)
									{
										continue;
									}
									string text3 = Encoding.Unicode.GetString(array);
									string text4 = Encoding.Default.GetString(array);

									// Extract file paths from PIDL structure
									MatchCollection mc1 = Regex.Matches(text3, @"[a-zA-Z]:\\[^<>""/|?*\x00-\x1F\r\n\t]+?\.[a-zA-Z0-9]{2,5}");
									MatchCollection mc2 = Regex.Matches(text4, @"[a-zA-Z]:\\[^<>""/|?*\x00-\x1F\r\n\t]+?\.[a-zA-Z0-9]{2,5}");

									List<string> foundPaths = new List<string>();
									foreach (Match m in mc1) foundPaths.Add(m.Value.Trim());
									foreach (Match m in mc2) foundPaths.Add(m.Value.Trim());

									// Also check raw string if no full path was parsed
									if (foundPaths.Count == 0)
									{
										string combined = (text3 + " " + text4).ToLowerInvariant();
										foreach (string cheat in CheatDatabases.ExtraCheatClients)
										{
											if (cheat.Length >= 4 && combined.Contains(cheat.ToLowerInvariant()) && !seenEntries.Contains(cheat))
											{
												seenEntries.Add(cheat);
												list.Add(string.Format("🔴 [5.01 - OpenSaveMRU .{0}] Выбор/скачивание софта [{1}] через диалог", text, cheat));
												break;
											}
										}
									}

									foreach (string fPath in foundPaths)
									{
										if (seenEntries.Contains(fPath)) continue;
										string fLower = fPath.ToLowerInvariant();
										if (CheatDatabases.IsWhitelistedPath(fLower)) continue;

										bool isCheat = false;
										string cheatName = "";
										foreach (string cheat in CheatDatabases.ExtraCheatClients)
										{
											if (cheat.Length >= 4 && CheatDetector.MatchesCheatName(fLower, cheat))
											{
												isCheat = true;
												cheatName = cheat;
												break;
											}
										}
										if (!isCheat)
										{
											foreach (string cl in CheatDetector.CheatClientNames)
											{
												if (CheatDetector.MatchesCheatName(fLower, cl))
												{
													isCheat = true;
													cheatName = cl;
													break;
												}
											}
										}

										seenEntries.Add(fPath);
										bool exists = File.Exists(fPath);
										if (isCheat)
										{
											if (!exists)
											{
												list.Add(string.Format("🗑️ [5.08 - Удалённый софт из OpenSaveMRU .{0}] Чит [{1}]: {2} [ФАЙЛ УДАЛЁН!]", text, cheatName, fPath));
											}
											else
											{
												list.Add(string.Format("🔴 [5.01 - Выбор софта в диалоге OpenSave .{0}] Чит [{1}]: {2}", text, cheatName, fPath));
											}
										}
										else if (!exists && (fLower.EndsWith(".exe") || fLower.EndsWith(".jar") || fLower.EndsWith(".dll")) &&
											(fLower.Contains("\\temp\\") || fLower.Contains("\\downloads\\") || fLower.Contains("\\desktop\\")))
										{
											list.Add(string.Format("⚠️ [5.08 - Удалённый исполняемый файл из OpenSaveMRU .{0}] {1}", text, fPath));
										}

										if (list.Count >= 30) break;
									}
								}
							}
							if (list.Count >= 30) break;
						}
					}
				}

				using (RegistryKey registryKey3 = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\ComDlg32\\LastVisitedPidlMRU"))
				{
					if (registryKey3 != null)
					{
						string[] valueNames2 = registryKey3.GetValueNames();
						foreach (string text6 in valueNames2)
						{
							if (text6 == "MRUListEx")
							{
								continue;
							}
							byte[] array2 = registryKey3.GetValue(text6) as byte[];
							if (array2 == null || array2.Length < 6)
							{
								continue;
							}
							string text7 = Encoding.Unicode.GetString(array2);
							string text7Default = Encoding.Default.GetString(array2);
							string text7Lower = (text7 + " " + text7Default).ToLowerInvariant();

							string[] extraCheatClients2 = CheatDatabases.ExtraCheatClients;
							foreach (string text8 in extraCheatClients2)
							{
								if (text8.Length >= 4 && text7Lower.IndexOf(text8, StringComparison.OrdinalIgnoreCase) >= 0 && !seenEntries.Contains(text8))
								{
									seenEntries.Add(text8);
									list.Add(string.Format("🚨 [5.08 - LastVisitedMRU] Посещение папки с софтом [{0}] через проводник/диалог", text8));
									break;
								}
							}
							if (list.Count >= 35)
							{
								break;
							}
						}
					}
				}
			}
			catch
			{
			}
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Диалоги открытия/сохранения файлов (OpenSavePidlMRU & LastVisitedPidlMRU)", list, (list.Count > 0) ? CheckSeverity.Critical : CheckSeverity.Info, "В истории файловых диалогов Windows OpenSavePidlMRU следов читов не найдено"));
			return list2;
		}

		public static List<CheckResult> RunArchiverHistoryCheck()
		{
			List<string> list = new List<string>();
			HashSet<string> seenArchives = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

			Tuple<RegistryHive, string>[] archiverSubKeys = new Tuple<RegistryHive, string>[]
			{
				// WinRAR
				Tuple.Create(RegistryHive.CurrentUser, "Software\\WinRAR\\ArcHistory"),
				Tuple.Create(RegistryHive.CurrentUser, "Software\\WinRAR\\DialogEditHistory\\ArcName"),
				Tuple.Create(RegistryHive.CurrentUser, "Software\\WinRAR\\DialogEditHistory\\ExtrPath"),
				Tuple.Create(RegistryHive.CurrentUser, "Software\\WinRAR\\DialogEditHistory\\SavePath"),
				Tuple.Create(RegistryHive.LocalMachine, "SOFTWARE\\WinRAR\\ArcHistory"),

				// 7-Zip (fixed from Software\a-Zip typo)
				Tuple.Create(RegistryHive.CurrentUser, "Software\\7-Zip\\FM\\History"),
				Tuple.Create(RegistryHive.CurrentUser, "Software\\7-Zip\\Compression\\History"),
				Tuple.Create(RegistryHive.CurrentUser, "Software\\7-Zip\\Extraction\\History"),
				Tuple.Create(RegistryHive.LocalMachine, "SOFTWARE\\7-Zip\\FM\\History"),
				Tuple.Create(RegistryHive.LocalMachine, "SOFTWARE\\WOW6432Node\\7-Zip\\FM\\History")
			};

			foreach (Tuple<RegistryHive, string> entry in archiverSubKeys)
			{
				try
				{
					RegistryKey baseKey = (entry.Item1 == RegistryHive.CurrentUser) ? Registry.CurrentUser : Registry.LocalMachine;
					using (RegistryKey regKey = baseKey.OpenSubKey(entry.Item2))
					{
						if (regKey == null) continue;
						string[] valNames = regKey.GetValueNames();
						foreach (string vn in valNames)
						{
							object valObj = regKey.GetValue(vn);
							if (valObj == null) continue;
							string arcPath = valObj.ToString().Trim();
							if (string.IsNullOrEmpty(arcPath) || seenArchives.Contains(arcPath)) continue;
							seenArchives.Add(arcPath);

							string arcLower = arcPath.ToLowerInvariant();
							if (CheatDatabases.IsWhitelistedPath(arcLower)) continue;

							bool isCheat = false;
							string cheatName = "";
							foreach (string ec in CheatDatabases.ExtraCheatClients)
							{
								if (ec.Length >= 4 && CheatDetector.MatchesCheatName(arcLower, ec))
								{
									isCheat = true;
									cheatName = ec;
									break;
								}
							}
							if (!isCheat)
							{
								foreach (string cl in CheatDetector.CheatClientNames)
								{
									if (CheatDetector.MatchesCheatName(arcLower, cl))
									{
										isCheat = true;
										cheatName = cl;
										break;
									}
								}
							}

							bool exists = File.Exists(arcPath) || Directory.Exists(arcPath);
							string sourceName = entry.Item2.Contains("WinRAR") ? "WinRAR" : "7-Zip";

							if (isCheat)
							{
								if (!exists)
								{
									list.Add(string.Format("🗑️ [5.08 - Удалённый чит-архив из {0}] Чит [{1}]: {2} [ФАЙЛ УДАЛЁН!]", sourceName, cheatName, arcPath));
								}
								else
								{
									list.Add(string.Format("🔴 [5.01 - Чит-архив в {0}] Чит [{1}]: {2}", sourceName, cheatName, arcPath));
								}
							}
							else if (!exists && (arcLower.EndsWith(".zip") || arcLower.EndsWith(".rar") || arcLower.EndsWith(".7z") || arcLower.EndsWith(".tar.gz")) &&
								(arcLower.Contains("\\temp\\") || arcLower.Contains("\\downloads\\") || arcLower.Contains("\\desktop\\") || arcLower.Contains("\\.minecraft\\")))
							{
								list.Add(string.Format("⚠️ [5.08 - Удалённый архив из {0}] {1}", sourceName, arcPath));
							}
						}
					}
				}
				catch
				{
				}
			}

			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "История архиваторов (WinRAR ArcHistory/DialogEdit & 7-Zip History)", list, (list.Count > 0) ? CheckSeverity.Critical : CheckSeverity.Info, "В истории архиваторов WinRAR и 7-Zip распаковки чит-архивов не зафиксировано"));
			return list2;
		}

