									if (string.IsNullOrEmpty(text6))
									{
										continue;
									}
									string text7 = text6.ToLowerInvariant();
									string[] extraCheatClients2 = CheatDatabases.ExtraCheatClients;
									foreach (string text8 in extraCheatClients2)
									{
										if (text8.Length >= 4 && text7.Contains(text8.ToLowerInvariant()))
										{
											list.Add(string.Format("\ud83d\udea8 [SearchHistory] Поисковый запрос софта: \"{0}\"", text6));
