		}

		public static List<CheckResult> RunWindowsDefenderEventCheck()
		{
			List<string> list = new List<string>();
			try
			{
				EventLogQuery eventLogQuery = new EventLogQuery("Microsoft-Windows-Windows Defender/Operational", PathType.LogName, "*[System[(EventID=1116 or EventID=1117 or EventID=5007)]]");
				eventLogQuery.ReverseDirection = true;
				using (EventLogReader eventLogReader = new EventLogReader(eventLogQuery))
				{
					int num = 0;
					EventRecord eventRecord;
					while ((eventRecord = eventLogReader.ReadEvent()) != null && num < 80)
					{
						using (eventRecord)
						{
							string text = "";
							try
							{
								text = eventRecord.FormatDescription();
							}
							catch
							{
							}
							string text2 = (eventRecord.TimeCreated.HasValue ? eventRecord.TimeCreated.Value.ToString("dd.MM.yyyy HH:mm:ss") : "—");
							if (eventRecord.Id == 1116 || eventRecord.Id == 1117)
							{
								string text3 = text.ToLowerInvariant();
								if (text3.Contains("autokms") || text3.Contains("kms") || text3.Contains("keygen") || text3.Contains("activator")) continue;
								bool flag = text3.Contains("vape") || text3.Contains("celestial") || text3.Contains("expensive") || text3.Contains("nursultan") || text3.Contains("wexside") || text3.Contains("killaura") || text3.Contains("deadcode") || text3.Contains("akrien") || text3.Contains("thunderhack");
								if (flag)
								{
									list.Add(string.Format("\ud83d\udea8 [Defender Event {0} | {1}] Антивирус блокировал чит: {2}", eventRecord.Id, text2, (text.Length > 200) ? (text.Substring(0, 200) + "...") : text));
								}
							}
							else if (eventRecord.Id == 5007)
							{
								string text5 = text.ToLowerInvariant();
								if (text5.Contains("исключен") || text5.Contains("exclusion") || text5.Contains(".jar") || text5.Contains(".dll"))
								{
									list.Add(string.Format("⚠\ufe0f [Defender Event 5007 | {0}] Добавлено исключение в Защитник: {1}", text2, (text.Length > 200) ? (text.Substring(0, 200) + "...") : text));
								}
							}
							num++;
							if (list.Count >= 25)
							{
								break;
							}
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				using (RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Microsoft\\Windows Defender\\Exclusions\\Paths"))
				{
					if (registryKey != null)
					{
						string[] valueNames = registryKey.GetValueNames();
						foreach (string arg in valueNames)
						{
							list.Add(string.Format("⚠\ufe0f [Defender Реестр] Папка-исключение антивируса: {0}", arg));
						}
					}
				}
			}
			catch
			{
			}
			bool flag2 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Защитник Windows (Блокировки читов и исключения EventID 1116/5007)", list, flag2 ? CheckSeverity.Critical : ((list.Count > 0) ? CheckSeverity.NeedsCheck : CheckSeverity.Info), "В журнале Защитника Windows блокировок чит-программ и подозрительных исключений не найдено"));
			return list2;
		}

		public static List<CheckResult> RunClipboardAndBitsCheck()
		{
			List<string> list = new List<string>();
			try
			{
				string text = null;
				if (Thread.CurrentThread.GetApartmentState() == ApartmentState.STA && Clipboard.ContainsText())
				{
					text = Clipboard.GetText();
				}
				if (!string.IsNullOrEmpty(text))
