		public static List<CheckResult> RunTimestompForensicsCheck()
		{
			List<string> list = new List<string>();
			DateTime now = DateTime.Now;

			// Check javaw process start time for live hot-swap detection
			DateTime javawStartTime = DateTime.MinValue;
			try
			{
				Process[] jps = Process.GetProcessesByName("javaw");
				if (jps.Length == 0) jps = Process.GetProcessesByName("java");
				if (jps.Length > 0) javawStartTime = jps[0].StartTime;
			}
			catch
			{
			}

			List<string> scanFolders = new List<string>();
			foreach (string root in MinecraftRoots())
			{
				scanFolders.Add(Path.Combine(root, "mods"));
				scanFolders.Add(Path.Combine(root, "versions"));
			}

			string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
			scanFolders.Add(Path.Combine(userProfile, ".feather", "user-mods"));
			scanFolders.Add(Path.Combine(userProfile, ".lunarclient", "offline", "multiver"));

			string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
			string prismInstances = Path.Combine(appData, "PrismLauncher", "instances");
			if (Directory.Exists(prismInstances))
			{
				try
				{
					foreach (string inst in Directory.GetDirectories(prismInstances))
					{
						scanFolders.Add(Path.Combine(inst, ".minecraft", "mods"));
						scanFolders.Add(Path.Combine(inst, "minecraft", "mods"));
					}
				}
				catch
				{
				}
			}

			HashSet<string> inspectedJars = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

			foreach (string folder in scanFolders)
			{
				if (!Directory.Exists(folder)) continue;
				try
				{
					string[] jarFiles = Directory.GetFiles(folder, "*.jar", SearchOption.AllDirectories);
					foreach (string jarPath in jarFiles)
					{
						if (inspectedJars.Contains(jarPath)) continue;
						inspectedJars.Add(jarPath);

						try
						{
							FileInfo fi = new FileInfo(jarPath);
							if (fi.Length < 1024) continue;

							// 1. Live hot-swap during Minecraft gameplay
							if (javawStartTime != DateTime.MinValue && fi.LastWriteTime > javawStartTime.AddSeconds(30))
							{
								list.Add(string.Format("🚨 [5.08 - Горячая подмена файла] JAR-файл {0} был изменён ВО ВРЕМЯ работы Minecraft ({1:dd.MM.yyyy HH:mm:ss}, игра запущена в {2:HH:mm:ss})!", fi.Name, fi.LastWriteTime, javawStartTime));
							}

							// 2. Inverted dates (CreationTime > LastWriteTime by > 30 days)
							if (fi.CreationTime > fi.LastWriteTime + TimeSpan.FromMinutes(2.0))
							{
								double diffDays = (fi.CreationTime - fi.LastWriteTime).TotalDays;
								if (diffDays > 30.0)
								{
									list.Add(string.Format("⚠️ [5.08 - Аномалия дат / Таймстомп] Мод {0}: дата изменения на {1:F0} дн. старше даты создания (Создан: {2:dd.MM.yyyy}, Изменён: {3:dd.MM.yyyy})", fi.Name, diffDays, fi.CreationTime, fi.LastWriteTime));
								}
							}

							// 3. Zero milliseconds (PowerShell $(Get-Item).LastWriteTime script artifact)
							// ZIP extracted timestamps naturally have 0 ms resolution - skip false positive

							// 4. Future dates
							if (fi.CreationTime > now.AddHours(2.0) || fi.LastWriteTime > now.AddHours(2.0))
							{
								list.Add(string.Format("🚨 [5.08 - Дата из будущего] {0}: время создания/изменения в будущем: {1:dd.MM.yyyy HH:mm}", fi.Name, (fi.CreationTime > fi.LastWriteTime) ? fi.CreationTime : fi.LastWriteTime));
							}
						}
						catch
						{
						}
					}
				}
				catch
				{
				}
			}

			bool flag = list.Any((string f) => f.StartsWith("🚨"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Аудит манипуляций со временем файлов (Timestomping & Hot-Swap)", list, flag ? CheckSeverity.Critical : ((list.Count > 0) ? CheckSeverity.NeedsCheck : CheckSeverity.Info), "Следов программного отката времени (Timestomp) и горячей подмены файлов в папках игры не обнаружено"));
			return list2;
		}

		public static List<CheckResult> RunCompiledAhkAndMacroProcessesCheck()
		{
			List<string> list = new List<string>();
			Process[] processes = Process.GetProcesses();
			Process[] array = processes;
			foreach (Process process in array)
			{
				try
				{
					if (process.Id == Process.GetCurrentProcess().Id)
					{
						continue;
					}
					string text = null;
					try
					{
						text = process.MainModule.FileName;
					}
					catch
					{
					}
					if (string.IsNullOrEmpty(text))
					{
						continue;
					}
					string text2 = text.ToLowerInvariant();
					if (!text2.StartsWith("c:\\windows\\") && !text2.StartsWith("c:\\program files\\") && !text2.StartsWith("c:\\program files (x86)\\"))
					{
						IntPtr mainWindowHandle = process.MainWindowHandle;
						if (!(mainWindowHandle != IntPtr.Zero))
						{
							goto IL_0118;
						}
						StringBuilder stringBuilder = new StringBuilder(256);
						GetClassName(mainWindowHandle, stringBuilder, 256);
						string text3 = stringBuilder.ToString();
						if (text3.IndexOf("AutoHotkey", StringComparison.OrdinalIgnoreCase) < 0)
						{
							goto IL_0118;
						}
						list.Add(string.Format("\ud83d\udea8 [Скомпилированный AHK макрос] Процесс {0} (PID: {1}, Путь: {2}) имеет класс окна AutoHotkey: {3}", process.ProcessName, process.Id, text, text3));
					}
					goto end_IL_001d;
					IL_0118:
					if (!File.Exists(text))
					{
						continue;
					}
					FileInfo fileInfo = new FileInfo(text);
					if (fileInfo.Length <= 204800 || fileInfo.Length >= 15728640)
					{
						continue;
					}
					using (FileStream fileStream = new FileStream(text, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
					{
						byte[] array2 = new byte[Math.Min(fileStream.Length, 524288L)];
						int count = fileStream.Read(array2, 0, array2.Length);
						string text4 = Encoding.ASCII.GetString(array2, 0, count);
						if (text4.Contains(">AUTOHOTKEY SCRIPT<") || (text4.Contains("AutoHotkey") && text4.Contains("Ahk2Exe")))
						{
							list.Add(string.Format("\ud83d\udea8 [Скомпилированный AHK кликер] Запущенный EXE {0} (PID: {1}, Путь: {2}) является скомпилированным скриптом AutoHotkey!", process.ProcessName, process.Id, text));
						}
					}
					end_IL_001d:;
				}
				catch
				{
				}
			}
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Процессы и память", "Скомпилированные AutoHotkey макросы и кликеры (Ahk2Exe)", list, flag ? CheckSeverity.Critical : ((list.Count > 0) ? CheckSeverity.NeedsCheck : CheckSeverity.Info), "Скомпилированных исполняемых файлов AutoHotkey в активных процессах не обнаружено"));
			return list2;
		}

		public static List<CheckResult> RunJvmPerfDataAndAttachCheck()
		{
