				}
				catch
				{
				}
			}
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Minecraft", "Аудит процессов Java HotSpot (hsperfdata / JVM Attach)", list, flag ? CheckSeverity.Critical : ((list.Count > 0) ? CheckSeverity.NeedsCheck : CheckSeverity.Info), "Скрытых или подозрительно закрытых Java процессов не обнаружено"));
			return list3;
		}

