			list2.Add(Make("Инжекции и перехваты", "Нативные библиотеки перехвата и хуки в Temp (JNA / JNativeHook)", list, flag2 ? CheckSeverity.Critical : ((list.Count > 0) ? CheckSeverity.NeedsCheck : CheckSeverity.Info), "Подозрительных или свежих нативных DLL в папке Temp не обнаружено"));
