							{
								continue;
							}
							string text2 = text.Substring("\\DosDevices\\".Length);
							object value = registryKey.GetValue(text);
							if (value is byte[])
							{
								byte[] bytes = (byte[])value;
								string text3 = Encoding.Unicode.GetString(bytes);
								char[] trimChars = new char[1];
								string text4 = text3.TrimEnd(trimChars);
								if (text4.Contains("USBSTOR"))
