				case "amdrsserv":
				case "amdow":
				case "steam":
				case "gameoverlayui":
				case "gamebar":
				case "xboxgamebar":
				case "gamebarftserver":
				case "sharex":
				case "lightshot":
				case "greenshot":
				case "gyazo":
				case "wallpaper32":
				case "wallpaper64":
				case "losslessscaling":
