		public static List<CheckResult> RunVolumeShadowCopiesAndRecoveryCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				List<CheckResult> list2 = new List<CheckResult>();
				list2.Add(Make("Криминалистика", "Теневые копии томов VSS и политики восстановления (vssadmin delete)", list, CheckSeverity.Info, "Служба VSS и политики теневого копирования активны для Windows."));
				return list2;
			}
			try
			{
				using (Process process = new Process())
				{
					process.StartInfo.FileName = "vssadmin.exe";
					process.StartInfo.Arguments = "list shadows";
					process.StartInfo.RedirectStandardOutput = true;
					process.StartInfo.RedirectStandardError = true;
					process.StartInfo.UseShellExecute = false;
					process.StartInfo.CreateNoWindow = true;
					process.Start();
					string text = process.StandardOutput.ReadToEnd();
					process.WaitForExit(3000);
					string text2 = text.ToLowerInvariant();
					if (text2.Contains("нет элементов") || text2.Contains("no items found") || text2.Contains("не найдено"))
					{
						double totalHours = TimeSpan.FromMilliseconds(Environment.TickCount).TotalHours;
						if (totalHours > 48.0)
						{
							list.Add(string.Format("⚠\ufe0f [VSS] В системе полностью отсутствуют теневые копии томов (uptime: {0:F1} ч) — возможно отключение VSS или зачистка через vssadmin delete shadows", totalHours));
						}
					}
					else if (text.Contains("Содержимое теневой копии") || text.Contains("Shadow Copy ID:"))
					{
						int count = Regex.Matches(text, "(?i)Shadow Copy ID:|Содержимое теневой копии").Count;
						list.Add(string.Format("ℹ\ufe0f [VSS] В системе активно теневых копий томов: {0}", count));
					}
				}
			}
			catch
			{
			}
			try
			{
				using (EventLogReader eventLogReader = new EventLogReader(new EventLogQuery("System", PathType.LogName, "*[System[(EventID=7036)]] and *[EventData[Data[1]='Теневое копирование тома' or Data[1]='Volume Shadow Copy']]")))
				{
					int num = 0;
					EventRecord eventRecord;
					while ((eventRecord = eventLogReader.ReadEvent()) != null && num < 10)
					{
						using (eventRecord)
						{
							if (eventRecord.TimeCreated.HasValue)
							{
								TimeSpan timeSpan = DateTime.Now - eventRecord.TimeCreated.Value;
								if (timeSpan.TotalHours < 24.0)
								{
									num++;
									list.Add(string.Format("⚠\ufe0f [VSS Event 7036] Изменение состояния службы VSS ({0:dd.MM.yyyy HH:mm:ss}, {1:F1} ч назад)", eventRecord.TimeCreated.Value, timeSpan.TotalHours));
								}
							}
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				using (Process process2 = new Process())
				{
					process2.StartInfo.FileName = "bcdedit.exe";
					process2.StartInfo.Arguments = "/enum {current}";
					process2.StartInfo.RedirectStandardOutput = true;
					process2.StartInfo.RedirectStandardError = true;
					process2.StartInfo.UseShellExecute = false;
					process2.StartInfo.CreateNoWindow = true;
					process2.Start();
					string text3 = process2.StandardOutput.ReadToEnd();
					process2.WaitForExit(3000);
					string text4 = text3.ToLowerInvariant();
					if (text4.Contains("recoveryenabled") && text4.Contains("no"))
					{
						list.Add("⚠\ufe0f [BCD Policy] Восстановление системы отключено: recoveryenabled = No");
					}
					if (text4.Contains("bootstatuspolicy") && text4.Contains("ignoreallfailures"))
					{
						list.Add("⚠\ufe0f [BCD Policy] Игнорирование сбоев загрузки: bootstatuspolicy = IgnoreAllFailures");
					}
				}
			}
			catch
			{
			}
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Криминалистика", "Теневые копии томов VSS и политики восстановления (vssadmin delete)", list, list.Any((string f) => f.StartsWith("\ud83d\udea8")) ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "Состояние теневых копий томов VSS и политик BCD штатное, признаков преднамеренного удаления не обнаружено"));
			return list3;
		}

