		public static List<CheckResult> RunZipEocdTrailingPayloadCheck()
		{
			List<string> list = new List<string>();
			foreach (string item in MinecraftRoots())
			{
				string path = Path.Combine(item, "mods");
				if (!Directory.Exists(path))
				{
					continue;
				}
				try
				{
					string[] files = Directory.GetFiles(path, "*.jar", SearchOption.AllDirectories);
					string[] array = files;
					foreach (string text in array)
					{
						try
						{
							FileInfo fileInfo = new FileInfo(text);
							if (fileInfo.Length < 100 || fileInfo.Length > 262144000)
							{
								continue;
							}
							using (FileStream fileStream = new FileStream(text, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
							{
								long length = fileStream.Length;
								int num = (int)Math.Min(65558L, length);
								byte[] array2 = new byte[num];
								fileStream.Seek(length - num, SeekOrigin.Begin);
								fileStream.Read(array2, 0, num);
								long num2 = -1L;
								int num3 = 0;
								for (int num4 = num - 22; num4 >= 0; num4--)
								{
									if (array2[num4] == 80 && array2[num4 + 1] == 75 && array2[num4 + 2] == 5 && array2[num4 + 3] == 6)
									{
										int num5 = array2[num4 + 20] | (array2[num4 + 21] << 8);
										num2 = length - num + num4;
										num3 = num5;
										break;
									}
								}
								if (num2 < 0)
								{
									continue;
								}
								long num6 = num2 + 22 + num3;
								long num7 = length - num6;
								if (num7 > 32)
								{
									fileStream.Seek(num6, SeekOrigin.Begin);
									byte[] array3 = new byte[Math.Min(128, (int)num7)];
									fileStream.Read(array3, 0, array3.Length);
									string text2 = Encoding.ASCII.GetString(array3);
									string text3 = "Скрытые данные";
									if (array3.Length >= 2 && array3[0] == 77 && array3[1] == 90)
									{
										text3 = "Внедрённый исполняемый PE-файл (.EXE/.DLL)";
									}
									else if (array3.Length >= 4 && array3[0] == 80 && array3[1] == 75 && array3[2] == 3 && array3[3] == 4)
									{
										text3 = "Внедрённый скрытый ZIP/JAR архив";
									}
									else if (text2.Contains("celestial") || text2.Contains("expensive") || text2.Contains("nursultan"))
									{
										text3 = "Маркер чита в скрытом хвосте";
									}
									list.Add(string.Format("\ud83d\udea8 [ZIP Steganography] Мод {0} содержит {1} байт скрытых данных после конца архива ({2})! Путь: {3}", Path.GetFileName(text), num7, text3, text));
								}
							}
						}
						catch
						{
						}
					}
				}
				catch
				{
				}
			}
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Аудит стеганографии и скрытых хвостов в модах (ZIP EOCD Trailing Data)", list, flag ? CheckSeverity.Critical : CheckSeverity.Info, "Все .jar моды имеют корректную ZIP-структуру, скрытых внедрённых данных после EOCD не обнаружено"));
			return list2;
		}

		public static List<CheckResult> RunSetupApiUsbTimelineCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				List<CheckResult> list2 = new List<CheckResult>();
				list2.Add(Make("Криминалистика", "Точная хронология подключений USB (setupapi.dev.log таймлайны)", list, CheckSeverity.Info, "Логирование драйверов setupapi.dev.log активно для Windows."));
				return list2;
			}
			try
			{
				string path = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "INF");
				string[] array = new string[2]
				{
					Path.Combine(path, "setupapi.dev.log"),
					Path.Combine(path, "setupapi.offline.log")
				};
				string[] array2 = array;
				foreach (string path2 in array2)
				{
					if (!File.Exists(path2))
					{
						continue;
					}
					string[] array3;
					using (FileStream stream = new FileStream(path2, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
					{
						using (StreamReader streamReader = new StreamReader(stream, Encoding.Default))
						{
							string text = streamReader.ReadToEnd();
							array3 = text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
						}
					}
					string text2 = null;
					foreach (string text3 in array3)
					{
						if (text3.StartsWith(">>>  [Device Install (Hardware initiated)") && text3.Contains("USB\\\\"))
						{
							text2 = text3;
						}
						else
						{
							if (text2 == null || !text3.StartsWith(">>>  Section start "))
							{
								continue;
							}
							string text4 = text3.Substring(19).Trim();
							DateTime result;
							if (DateTime.TryParse(text4.Split('.')[0], out result))
							{
								TimeSpan timeSpan = DateTime.Now - result;
								string text5 = text2;
								int num = text5.IndexOf("USB\\\\");
								if (num >= 0)
								{
									text5 = text5.Substring(num).TrimEnd(']');
								}
								if (timeSpan.TotalHours < 2.0 && timeSpan.TotalMinutes >= 0.0)
								{
									list.Add(string.Format("\ud83d\udea8 [Свежая флешка перед проверкой / {0:F0} мин назад] {1} ({2:dd.MM.yyyy HH:mm:ss})", timeSpan.TotalMinutes, text5, result));
								}
								else if (timeSpan.TotalHours < 24.0 && timeSpan.TotalHours >= 0.0)
								{
									list.Add(string.Format("⚠\ufe0f [Подключение USB за 24 ч / {0:F1} ч назад] {1} ({2:dd.MM.yyyy HH:mm:ss})", timeSpan.TotalHours, text5, result));
								}
								else if (timeSpan.TotalDays < 7.0 && timeSpan.TotalDays >= 0.0)
								{
									list.Add(string.Format("ℹ\ufe0f [Подключение USB за неделю / {0:F0} дн назад] {1} ({2:dd.MM.yyyy HH:mm})", timeSpan.TotalDays, text5, result));
								}
							}
							text2 = null;
						}
					}
				}
			}
			catch
			{
			}
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Криминалистика", "Точная хронология подключений USB (setupapi.dev.log таймлайны)", list, flag ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "Свежих подключений USB-накопителей непосредственно перед проверкой (менее 24 ч) не зафиксировано"));
			return list3;
		}

		public static List<CheckResult> RunJvmHotspotCrashLogCheck()
		{
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
