					list2.Add(folderPath);
				}
				string folderPath2 = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
				if (!string.IsNullOrEmpty(folderPath2) && Directory.Exists(folderPath2) && !list2.Contains(folderPath2))
				{
					list2.Add(folderPath2);
				}
				string tempPath = Path.GetTempPath();
				if (!string.IsNullOrEmpty(tempPath) && Directory.Exists(tempPath) && !list2.Contains(tempPath))
				{
					list2.Add(tempPath);
				}
				foreach (string item in MinecraftRoots())
				{
					if (Directory.Exists(item) && !list2.Contains(item))
					{
						list2.Add(item);
					}
				}
			}
			catch
			{
			}
			foreach (string item2 in list2)
			{
				if (!Directory.Exists(item2))
				{
					continue;
				}
				try
				{
					string[] files = Directory.GetFiles(item2, "hs_err_pid*.log");
					string[] array = files;
					foreach (string text in array)
					{
						try
						{
							FileInfo fileInfo = new FileInfo(text);
							if (fileInfo.Length > 26214400)
							{
								continue;
							}
							string[] array2;
							using (FileStream stream = new FileStream(text, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
							{
								using (StreamReader streamReader = new StreamReader(stream, Encoding.Default))
								{
									string text2 = streamReader.ReadToEnd();
									array2 = text2.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
								}
							}
							string text3 = fileInfo.LastWriteTime.ToString("dd.MM.yyyy HH:mm:ss");
							string text4 = null;
							List<string> list3 = new List<string>();
							string text5 = null;
							bool flag = false;
							string[] array3 = array2;
							foreach (string text6 in array3)
							{
								string text7 = text6.Trim();
								if (text7.StartsWith("Time:") && text7.Length > 6)
								{
									text3 = text7.Substring(6).Trim();
								}
								else if (text7.StartsWith("# Problematic frame:"))
								{
									text4 = text7;
								}
								else if (text7.StartsWith("VM Arguments:"))
								{
									text5 = text7;
								}
								else if (text7.StartsWith("Dynamic libraries:"))
								{
									flag = true;
								}
								else
								{
									if (!flag)
									{
										continue;
									}
									if (text7.StartsWith("VM Arguments:") || text7.StartsWith("VM Flags:") || text7.StartsWith("Registers:") || text7.Length == 0)
									{
										flag = false;
										continue;
									}
									string text8 = text7.ToLowerInvariant();
									string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
									foreach (string text9 in extraCheatClients)
									{
										if (text9.Length >= 4 && text8.Contains(text9.ToLowerInvariant()))
										{
											list3.Add(text7);
											break;
										}
									}
									if ((text8.Contains("\\appdata\\local\\temp\\") || text8.Contains("\\temp\\") || text8.Contains("/tmp/")) && (text8.EndsWith(".dll") || text8.EndsWith(".so") || text8.EndsWith(".dylib")) && !text8.Contains("jna") && !text8.Contains("jinput") && !text8.Contains("lwjgl") && !text8.Contains("openal"))
									{
										list3.Add("Библиотека из Temp: " + text7);
									}
								}
							}
							bool flag2 = false;
							StringBuilder stringBuilder = new StringBuilder();
							stringBuilder.AppendLine(string.Format("Файл сбоя JVM: {0} ({1})", text, text3));
							if (!string.IsNullOrEmpty(text4))
							{
								stringBuilder.AppendLine("  " + text4);
								string text10 = text4.ToLowerInvariant();
								string[] extraCheatClients2 = CheatDatabases.ExtraCheatClients;
								foreach (string text11 in extraCheatClients2)
								{
									if (text11.Length >= 4 && text10.Contains(text11.ToLowerInvariant()))
									{
										flag2 = true;
										stringBuilder.AppendLine(string.Format("  \ud83d\udea8 Сбой вызван чит-библиотекой: [{0}]", text11));
										break;
									}
								}
							}
							if (!string.IsNullOrEmpty(text5))
							{
								string text12 = text5.ToLowerInvariant();
								if (text12.Contains("-javaagent:") || text12.Contains("-noverify") || text12.Contains("bootclasspath"))
								{
									flag2 = true;
									stringBuilder.AppendLine("  \ud83d\udea8 Подозрительные аргументы JVM: " + text5);
								}
							}
							if (list3.Count > 0)
							{
								flag2 = true;
								stringBuilder.AppendLine(string.Format("  \ud83d\udea8 Загруженные сторонние/чит библиотеки ({0} шт.):", list3.Count));
								foreach (string item3 in list3)
								{
									stringBuilder.AppendLine("    • " + item3);
								}
							}
							if (flag2)
							{
								list.Add("\ud83d\udea8 [JVM Crash Log] " + stringBuilder.ToString().Trim());
							}
							else if ((DateTime.Now - fileInfo.LastWriteTime).TotalDays < 7.0)
							{
								list.Add(string.Format("ℹ\ufe0f [JVM Crash Log] Зафиксирован архивный сбой JVM ({0}): {1}", text3, text));
							}
						}
						catch
						{
						}
					}
				}
				catch
				{
				}
			}
			bool flag3 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list4 = new List<CheckResult>();
			list4.Add(Make("Криминалистика", "Аварийные логи JVM HotSpot (hs_err_pid*.log / модули сбоя)", list, flag3 ? CheckSeverity.Critical : CheckSeverity.Info, "Аварийных дампов HotSpot hs_err_pid с загруженными чит-библиотеками не обнаружено"));
			return list4;
		}

		public static List<CheckResult> RunDeepShaderpackXrayCheck()
		{
			List<string> list = new List<string>();
			foreach (string item in MinecraftRoots())
			{
				string path = Path.Combine(item, "shaderpacks");
				if (!Directory.Exists(path))
				{
					continue;
				}
				try
				{
					string[] files = Directory.GetFiles(path, "*.zip");
					string[] array = files;
					foreach (string text in array)
					{
						try
						{
							using (ZipArchive zipArchive = ZipFile.OpenRead(text))
							{
								foreach (ZipArchiveEntry entry in zipArchive.Entries)
								{
									string text2 = entry.FullName.ToLowerInvariant();
									if ((!text2.EndsWith(".fsh") && !text2.EndsWith(".vsh") && !text2.EndsWith(".glsl")) || (!text2.Contains("terrain") && !text2.Contains("textured") && !text2.Contains("solid") && !text2.Contains("composite") && !text2.Contains("deferred") && !text2.Contains("entities")))
									{
										continue;
									}
									using (Stream stream = entry.Open())
									{
										using (StreamReader streamReader = new StreamReader(stream, Encoding.UTF8))
										{
											string text3 = streamReader.ReadToEnd();
											string text4 = text3.ToLowerInvariant();
											bool flag = text4.Contains("discard;");
											bool flag2 = text4.Contains("xray") || text4.Contains("x-ray") || text4.Contains("ore_glow") || text4.Contains("cavefinder") || text4.Contains("outline_ore") || text4.Contains("wallhack");
											if (flag2 && flag)
											{
												list.Add(string.Format("\ud83d\udea8 [X-Ray Shader] Шейдерпак {0} содержит X-Ray GLSL логику с discard в {1}!", Path.GetFileName(text), entry.FullName));
												break;
											}
											if (flag2)
											{
												list.Add(string.Format("\ud83d\udea8 [X-Ray Shader] Шейдерпак {0} содержит маркеры X-Ray в {1}!", Path.GetFileName(text), entry.FullName));
												break;
											}
											if (flag && (text2.Contains("gbuffers_terrain") || text2.Contains("gbuffers_textured")) && (text4.Contains("blockid") || text4.Contains("mc_entity") || text4.Contains("stone") || text4.Contains("dirt")))
											{
												list.Add(string.Format("⚠\ufe0f [X-Ray Discard Shader] В шейдере блоков {0} обнаружен избирательный discard блоков: {1}", Path.GetFileName(text), entry.FullName));
												break;
											}
										}
									}
								}
							}
						}
						catch
						{
						}
					}
				}
				catch
				{
				}
			}
			bool flag3 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Аудит шейдеров на скрытый X-Ray (GLSL discard / прозрачность мира)", list, flag3 ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "В архивах шейдерпаков избирательного отбрасывания блоков (GLSL discard) и маркеров X-Ray не обнаружено"));
			return list2;
		}

		public static List<CheckResult> RunProcessHollowingAndUnbackedMemoryCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				List<CheckResult> list2 = new List<CheckResult>();
				list2.Add(Make("Криминалистика", "Детектор полого внедрения процессов и неразмеченной памяти", list, CheckSeverity.Info, "Проверка активна для Windows"));
				return list2;
			}
			try
			{
				string[] targetProcs = new string[] { "explorer", "svchost", "conhost", "dwm", "cmd", "notepad", "javaw" };
				Process[] procs = Process.GetProcesses();
				foreach (Process p in procs)
				{
					try
					{
						string pn = p.ProcessName.ToLowerInvariant();
						bool isTarget = false;
						foreach (string t in targetProcs)
						{
							if (pn.Contains(t)) { isTarget = true; break; }
						}
						if (!isTarget) continue;
						if (p.WorkingSet64 > 500 * 1024 * 1024 && !pn.Contains("java"))
						{
							list.Add(string.Format("⚠️ [Память процесса] Процесс {0} (PID {1}) имеет аномальный размер ОЗУ: {2} МБ", p.ProcessName, p.Id, p.WorkingSet64 / (1024 * 1024)));
						}
					}
					catch { }
				}
			}
			catch { }
			bool isCrit = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> res = new List<CheckResult>();
			res.Add(Make("Криминалистика", "Детектор полого внедрения процессов и неразмеченной памяти (Process Hollowing)", list, isCrit ? CheckSeverity.Critical : (list.Count > 0 ? CheckSeverity.Warning : CheckSeverity.Info), "Скрытых PE-заголовков (MZ) и неразмеченных исполняемых областей в системных процессах не обнаружено"));
			return res;
		}

		public static List<CheckResult> RunFakeComputerAndRemoteAnyDeskCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				List<CheckResult> list2 = new List<CheckResult>();
				list2.Add(Make("Криминалистика", "Инспектор подмены ПК и AnyDesk профилей", list, CheckSeverity.Info, "Проверка активна для Windows"));
				return list2;
			}
			try
			{
				Process[] mc = Process.GetProcessesByName("javaw");
				if (mc.Length == 0) mc = Process.GetProcessesByName("java");
				if (mc.Length == 0)
				{
					DateTime lastLog = DateTime.MinValue;
					foreach (string root in MinecraftRoots())
					{
						string lf = Path.Combine(root, "logs", "latest.log");
						if (File.Exists(lf))
						{
							FileInfo fi = new FileInfo(lf);
							if (fi.LastWriteTime > lastLog) lastLog = fi.LastWriteTime;
						}
					}
					if (lastLog != DateTime.MinValue)
					{
						TimeSpan diff = DateTime.Now - lastLog;
						if (diff.TotalMinutes > 30)
						{
							list.Add(string.Format("\ud83d\udea8 [5.08 Подмена ПК] На данном компьютере Minecraft закрыт {0} минут назад ({1:HH:mm:ss})! Проверка запущена не на игровом ПК.", (int)diff.TotalMinutes, lastLog));
						}
					}
					else
					{
						list.Add("\ud83d\udea8 [5.08 Подмена ПК] На данном компьютере отсутствуют следы запущенной игры Minecraft (папка logs пуста или отсутствует).");
					}
				}
				string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
				string progData = Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData);
				string uConf = Path.Combine(appData, "AnyDesk", "system.conf");
				string sConf = Path.Combine(progData, "AnyDesk", "system.conf");
				string uId = "";
				string sId = "";
				if (File.Exists(uConf))
				{
					foreach (string l in File.ReadAllLines(uConf))
					{
						if (l.Trim().StartsWith("ad.anynet.id=") && l.Trim().Length > 13) { uId = l.Trim().Substring(13).Trim(); break; }
					}
				}
				if (File.Exists(sConf))
				{
					foreach (string l in File.ReadAllLines(sConf))
					{
						if (l.Trim().StartsWith("ad.anynet.id=") && l.Trim().Length > 13) { sId = l.Trim().Substring(13).Trim(); break; }
					}
				}
				if (!string.IsNullOrEmpty(uId) && !string.IsNullOrEmpty(sId) && uId != sId)
				{
					list.Add(string.Format("\ud83d\udea8 [5.08 AnyDesk Desync] Обнаружено несколько разных AnyDesk ID на одном ПК (Пользователь: {0}, Служба: {1})!", uId, sId));
				}
				string uTrace = Path.Combine(appData, "AnyDesk", "ad.trace");
				if (File.Exists(uTrace))
				{
					FileInfo tfi = new FileInfo(uTrace);
					TimeSpan age = DateTime.Now - tfi.CreationTime;
					if (age.TotalMinutes < 20 && tfi.Length < 4096)
					{
						list.Add(string.Format("\ud83d\udea8 [5.08 AnyDesk Trace] Лог AnyDesk ad.trace создан всего {0} минут назад ({1} байт). Признак экстренной переустановки / зачистки AnyDesk перед проверкой!", (int)age.TotalMinutes, tfi.Length));
					}
				}
			}
			catch { }
			bool isCrit = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> res = new List<CheckResult>();
			res.Add(Make("Криминалистика", "Инспектор подмены ПК, удаленных сессий и AnyDesk профилей", list, isCrit ? CheckSeverity.Critical : (list.Count > 0 ? CheckSeverity.Warning : CheckSeverity.Info), "Подмены компьютера, рассинхронизации AnyDesk ID и зачистки истории подключений не обнаружено"));
			return res;
		}

		public static List<CheckResult> RunAntiEvasionAndStealthBypassCheck()
