				string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
				foreach (string text6 in extraCheatClients)
				{
					if (text6.Length >= 4)
					{
						string text7 = text6.ToLowerInvariant();
						string valJar = text7 + ".jar";
						string valExe = text7 + ".exe";
						string valDll = text7 + ".dll";
						string valZip = text7 + ".zip";
						if (text4.Contains(valJar) || text4.Contains(valExe) || text4.Contains(valDll) || text4.Contains(valZip))
						{
							string hitKey = browserName + ":download:" + text6;
							if (!seenHits.Contains(hitKey))
							{
								seenHits.Add(hitKey);
								list.Add(string.Format("🚨 [5.01 - Browser Download] {0}: обнаружена загрузка чит-файла: [{1}]", browserName, text6));
							}
						}
					}
				}
			}

			bool flag = list.Any((string f) => f.StartsWith("🚨"));
			List<CheckResult> list4 = new List<CheckResult>();
			list4.Add(Make("Криминалистика", "Аудит истории браузеров и загрузок (Chrome, Edge, Firefox, Yandex)", list, flag ? CheckSeverity.Critical : CheckSeverity.Info, "Следов посещения чит-доменов или загрузок чит-файлов в истории браузеров не зафиксировано"));
			return list4;
		}

