		private static string DecodeRot13String(string input)
		{
			if (string.IsNullOrEmpty(input))
			{
				return "";
			}
			char[] array = input.ToCharArray();
			for (int i = 0; i < array.Length; i++)
			{
				int num = array[i];
				switch (num)
				{
				case 110:
				case 111:
				case 112:
				case 113:
				case 114:
				case 115:
				case 116:
				case 117:
				case 118:
				case 119:
				case 120:
				case 121:
				case 122:
					num -= 13;
					break;
				case 97:
				case 98:
				case 99:
				case 100:
				case 101:
				case 102:
				case 103:
				case 104:
				case 105:
				case 106:
				case 107:
				case 108:
				case 109:
					num += 13;
					break;
				default:
					switch (num)
					{
					case 78:
					case 79:
					case 80:
					case 81:
					case 82:
					case 83:
					case 84:
					case 85:
					case 86:
					case 87:
					case 88:
					case 89:
					case 90:
						num -= 13;
						break;
					case 65:
					case 66:
					case 67:
					case 68:
					case 69:
					case 70:
					case 71:
					case 72:
					case 73:
					case 74:
					case 75:
					case 76:
					case 77:
						num += 13;
						break;
					}
					break;
				}
				array[i] = (char)num;
			}
			return new string(array);
		}

