		public static List<CheckResult> RunActiveJavaNetworkConnectionsCheck()
		{
			List<string> list = new List<string>();
			try
			{
				List<NetworkSocketItem> activeMinecraftSockets = NetworkAndRemoteForensics.GetActiveMinecraftSockets();
				if (activeMinecraftSockets.Count != 0)
				{
					foreach (NetworkSocketItem item in activeMinecraftSockets)
					{
						string text = ((item.RemoteEndpoint != null) ? item.RemoteEndpoint.Trim() : "");
						string text2 = text.ToLowerInvariant();
						if (text2.StartsWith("127.0.0.1") || text2.StartsWith("localhost") || text2.StartsWith("[::1]"))
						{
							list.Add(string.Format("\ud83d\udea8 [Localhost Proxy Socket] {0} (PID {1}) подключен к локальному сокету {2} (признак локального прокси/инжектора чита, например Slinky/Vape)!", item.ProcessName, item.Pid, text));
							continue;
						}
						int num = text.LastIndexOf(':');
						int result;
						if (num > 0 && num < text.Length - 1 && int.TryParse(text.Substring(num + 1), out result))
						{
							if (result == 25565 || (result >= 25500 && result <= 25600))
							{
								list.Add(string.Format("ℹ\ufe0f [Minecraft Server] {0} подключен к стандартному игровому серверу: {1}", item.ProcessName, text));
							}
							else if (result == 80 || result == 443 || result == 8080)
							{
								list.Add(string.Format("ℹ\ufe0f [Web Connection] {0} поддерживает стандартное веб-соединение (порт {1}): {2}", item.ProcessName, result, text));
							}
							else
							{
								list.Add(string.Format("ℹ\ufe0f [Game Connection] {0} сокет: {1} ({2})", item.ProcessName, text, item.State));
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("Ошибка аудита сокетов: " + ex.Message);
			}
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Криминалистика", "Аудит активных сетевых соединений Java (Local Proxy & WebSocket)", list, flag ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "Подозрительных локальных прокси-сокетов (127.0.0.1) у процессов Java не зафиксировано"));
			return list2;
		}

