				using (EventLogReader eventLogReader = new EventLogReader(eventQuery))
				{
					int num = 0;
					EventRecord eventRecord;
					while ((eventRecord = eventLogReader.ReadEvent()) != null && num < 30)
					{
						DateTime? timeCreated = eventRecord.TimeCreated;
						if (timeCreated.HasValue && (DateTime.Now - timeCreated.Value).TotalDays < 3.0)
						{
							string text = eventRecord.FormatDescription();
							if (!string.IsNullOrEmpty(text))
							{
