									if (text2.Contains(text3))
									{
										if (eventRecord.Id == 7040 && (text2.Contains("disabled") || text2.Contains("отключена") || text2.Contains("отключено")))
										{
											list.Add(string.Format("\ud83d\udea8 [Service Tampering Disabled] Служба {0} была переведена в состояние ОТКЛЮЧЕНА (Event 7040, {1:dd.MM.yyyy HH:mm:ss})!", text3.ToUpperInvariant(), timeCreated.Value));
											break;
										}
