										{
											list.Add(string.Format("⚠\ufe0f [Service Tampering Stopped] Служба {0} была ОСТАНОВЛЕНА (Event 7036, {1:dd.MM.yyyy HH:mm:ss})!", text3.ToUpperInvariant(), timeCreated.Value));
											break;
										}
									}
								}
							}
						}
						num++;
					}
				}
			}
			catch
			{
			}
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Криминалистика", "Аудит изменения и остановки служб (EventID 7040 / 7036)", list, flag ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "Фактов отключения или остановки критических криминалистических служб (PcaSvc, DPS, BAM, SysMain) не зафиксировано"));
			return list3;
		}

