		private static extern IntPtr FindFirstStreamW(string lpFileName, int InfoLevel, ref WIN32_FIND_STREAM_DATA lpFindStreamData, int dwFlags);

		[DllImport("kernel32.dll", CharSet = CharSet.Unicode, ExactSpelling = true, SetLastError = true)]
