		public static List<CheckResult> RunNtfsHiddenAlternateStreamsCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				List<CheckResult> list2 = new List<CheckResult>();
				list2.Add(Make("Криминалистика", "Аудит скрытых альтернативных потоков NTFS (ADS)", list, CheckSeverity.Info, "Потоки ADS специфичны для файловой системы NTFS Windows"));
				return list2;
			}
			try
			{
				List<string> list3 = new List<string>();
				foreach (string item in MinecraftRoots())
				{
					if (Directory.Exists(item))
					{
						string text = Path.Combine(item, "mods");
						if (Directory.Exists(text))
						{
							list3.Add(text);
						}
						list3.Add(item);
					}
				}
				string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
				if (Directory.Exists(folderPath))
				{
					list3.Add(folderPath);
				}
				foreach (string item2 in list3)
				{
					if (!Directory.Exists(item2))
					{
						continue;
					}
					string[] files = Directory.GetFiles(item2, "*.*");
					string[] array = files;
					foreach (string text2 in array)
					{
						string text3 = Path.GetExtension(text2).ToLowerInvariant();
						if (text3 != ".jar" && text3 != ".exe" && text3 != ".dll" && text3 != ".txt" && text3 != ".json" && text3 != ".bat")
						{
							continue;
						}
						try
						{
							WIN32_FIND_STREAM_DATA lpFindStreamData = default(WIN32_FIND_STREAM_DATA);
							IntPtr intPtr = FindFirstStreamW(text2, 0, ref lpFindStreamData, 0);
							if (!(intPtr != (IntPtr)(-1)) || !(intPtr != IntPtr.Zero))
							{
								continue;
							}
							try
							{
								do
								{
									string cStreamName = lpFindStreamData.cStreamName;
									if (cStreamName != "::$DATA" && !cStreamName.Equals(":Zone.Identifier:$DATA", StringComparison.OrdinalIgnoreCase))
									{
										list.Add(string.Format("\ud83d\udea8 [NTFS Hidden Stream] В файле {0} обнаружен скрытый альтернативный поток данных: {1} (размер: {2} байт)!", Path.GetFileName(text2), cStreamName, lpFindStreamData.StreamSize));
									}
								}
								while (FindNextStreamW(intPtr, ref lpFindStreamData));
							}
							finally
							{
								FindClose(intPtr);
							}
						}
						catch
						{
						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("Ошибка проверки потоков ADS: " + ex.Message);
			}
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list4 = new List<CheckResult>();
			list4.Add(Make("Криминалистика", "Аудит скрытых альтернативных потоков NTFS (ADS)", list, flag ? CheckSeverity.Critical : CheckSeverity.Info, "Скрытых альтернативных потоков данных (стеганографии/сокрытия пейлоадов) в файлах не обнаружено"));
			return list4;
		}

