		private static List<string> ExtractStringsFromPidl(byte[] data)
		{
			List<string> list = new List<string>();
			if (data == null || data.Length == 0)
			{
				return list;
			}
			List<char> list2 = new List<char>();
			foreach (byte b in data)
			{
				if (b >= 32 && b <= 126)
				{
					list2.Add((char)b);
					continue;
				}
				if (list2.Count >= 4)
				{
					string text = new string(list2.ToArray()).Trim();
					if (text.Contains(".") && text.Length > 4)
					{
						list.Add(text);
					}
				}
				list2.Clear();
			}
			if (list2.Count >= 4)
			{
				string text2 = new string(list2.ToArray()).Trim();
				if (text2.Contains(".") && text2.Length > 4)
				{
					list.Add(text2);
				}
			}
			List<char> list3 = new List<char>();
			for (int j = 0; j < data.Length - 1; j += 2)
			{
				ushort num = (ushort)(data[j] | (data[j + 1] << 8));
				if ((num >= 32 && num <= 126) || (num >= 1024 && num <= 1279))
				{
					list3.Add((char)num);
					continue;
				}
				if (list3.Count >= 4)
				{
					string text3 = new string(list3.ToArray()).Trim();
					if (text3.Contains(".") && text3.Length > 4)
					{
						list.Add(text3);
					}
				}
				list3.Clear();
			}
			if (list3.Count >= 4)
			{
				string text4 = new string(list3.ToArray()).Trim();
				if (text4.Contains(".") && text4.Length > 4)
				{
					list.Add(text4);
				}
			}
			return list.Distinct().ToList();
		}

