		public static List<CheckResult> RunSystemCrashAndRebootEvasionCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			try
			{
				ProcessStartInfo processStartInfo = new ProcessStartInfo("wevtutil.exe", "qe System \"/q:*[System[(EventID=41 or EventID=6008 or EventID=1001 or EventID=2004)]]\" /c:15 /rd:true /f:text");
				processStartInfo.UseShellExecute = false;
				processStartInfo.RedirectStandardOutput = true;
				processStartInfo.CreateNoWindow = true;
				processStartInfo.StandardOutputEncoding = Encoding.GetEncoding(866);
				ProcessStartInfo startInfo = processStartInfo;
				using (Process process = Process.Start(startInfo))
				{
					if (process != null)
					{
						string text = process.StandardOutput.ReadToEnd();
						process.WaitForExit(3000);
						string[] array = text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
						string text2 = "";
						string text3 = "";
						for (int i = 0; i < array.Length; i++)
						{
							string text4 = array[i].Trim();
							if (text4.StartsWith("Event ID:"))
							{
								text2 = text4.Substring("Event ID:".Length).Trim();
							}
							else if (text4.StartsWith("Date:"))
							{
								text3 = text4.Substring("Date:".Length).Trim();
							}
							else if (text4.StartsWith("Source:"))
							{
								text4.Substring("Source:".Length).Trim();
							}
							if (string.IsNullOrEmpty(text2) || string.IsNullOrEmpty(text3) || (!text4.StartsWith("Event[") && i != array.Length - 1))
							{
								continue;
							}
							DateTime result;
							if (DateTime.TryParse(text3, out result))
							{
								TimeSpan timeSpan = DateTime.UtcNow - result.ToUniversalTime();
								if (timeSpan.TotalDays <= 3.0)
								{
									object obj;
									switch (text2)
									{
									default:
										obj = "Критическое исчерпание виртуальной памяти (OOM Resource Exhaustion)";
										break;
									case "1001":
										obj = "Критический сбой синего экрана (BSOD BugCheck)";
										break;
									case "6008":
										obj = "Неожиданное завершение работы системы (Dirty Shutdown)";
										break;
									case "41":
										obj = "Аварийная перезагрузка / выключение питания (Kernel-Power)";
										break;
									}
									string text5 = (string)obj;
									if (timeSpan.TotalHours <= 24.0)
									{
										list.Add(string.Format("\ud83d\udea8 [Recent Hard Reboot | {0:dd.MM.yyyy HH:mm}] {1} (EventID {2}, {3:F1} ч назад)", result.ToLocalTime(), text5, text2, timeSpan.TotalHours));
									}
									else
									{
										list.Add(string.Format("⚠\ufe0f [System Crash Event | {0:dd.MM.yyyy HH:mm}] {1} (EventID {2}, {3:F1} ч назад)", result.ToLocalTime(), text5, text2, timeSpan.TotalHours));
									}
								}
							}
							text2 = "";
							text3 = "";
						}
					}
				}
			}
			catch
			{
			}
			list = list.Distinct().ToList();
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Журнал системы", "Аудит аварийных выключений, перезагрузок и BSOD (EventID 41/6008/1001)", list, flag ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "Фактов аварийных выключений, перезагрузок питания или синих экранов BSOD за последние 72 часа не зафиксировано"));
			return list2;
		}

