		public static List<CheckResult> RunSteamNonSteamShortcutsForensicsCheck()
		{
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			if (PlatformHelper.IsWindows)
			{
				string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86);
				string folderPath2 = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);
				if (Directory.Exists(Path.Combine(folderPath, "Steam\\userdata")))
				{
					list2.Add(Path.Combine(folderPath, "Steam\\userdata"));
				}
				if (Directory.Exists(Path.Combine(folderPath2, "Steam\\userdata")))
				{
					list2.Add(Path.Combine(folderPath2, "Steam\\userdata"));
				}
				DriveInfo[] drives = DriveInfo.GetDrives();
				foreach (DriveInfo driveInfo in drives)
				{
					try
					{
						if (driveInfo.IsReady)
						{
							string text = Path.Combine(driveInfo.RootDirectory.FullName, "Steam\\userdata");
							if (Directory.Exists(text))
							{
								list2.Add(text);
							}
						}
					}
					catch
					{
					}
				}
			}
			foreach (string item in list2.Distinct())
			{
				try
				{
					string[] directories = Directory.GetDirectories(item);
					string[] array = directories;
					foreach (string path in array)
					{
						string path2 = Path.Combine(path, "config\\shortcuts.vdf");
						if (!File.Exists(path2))
						{
							continue;
						}
						try
						{
							byte[] array2 = File.ReadAllBytes(path2);
							if (array2.Length <= 20)
							{
								continue;
							}
							List<string> list3 = new List<string>();
							List<char> list4 = new List<char>();
							foreach (byte b in array2)
							{
								if (b >= 32 && b <= 126)
								{
									list4.Add((char)b);
									continue;
								}
								if (list4.Count >= 4)
								{
									list3.Add(new string(list4.ToArray()).Trim());
								}
								list4.Clear();
							}
							if (list4.Count >= 4)
							{
								list3.Add(new string(list4.ToArray()).Trim());
							}
							for (int l = 0; l < list3.Count; l++)
							{
								string text2 = list3[l];
								string text3 = text2.ToLowerInvariant();
								string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
								foreach (string text4 in extraCheatClients)
								{
									if (text4.Length >= 4 && text3.Contains(text4.ToLowerInvariant()))
									{
										list.Add(string.Format("\ud83d\udea8 [Steam Non-Steam Cheat Shortcut] Сторонний ярлык чита добавлен в Steam: \"{0}\"", text2));
										break;
