		public static List<CheckResult> RunActiveTcpListeningEndpointsCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			try
			{
				ProcessStartInfo processStartInfo = new ProcessStartInfo("netstat", "-ano -p tcp");
				processStartInfo.UseShellExecute = false;
				processStartInfo.RedirectStandardOutput = true;
				processStartInfo.CreateNoWindow = true;
				processStartInfo.StandardOutputEncoding = Encoding.GetEncoding(866);
				ProcessStartInfo startInfo = processStartInfo;
				using (Process process = Process.Start(startInfo))
				{
					if (process != null)
					{
						string text = process.StandardOutput.ReadToEnd();
						process.WaitForExit(3000);
						string[] array = text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
						for (int i = 0; i < array.Length; i++)
						{
							string text2 = array[i].Trim();
							string[] array2 = text2.Split(new char[2] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
							if (array2.Length < 5 || !(array2[0].ToUpperInvariant() == "TCP") || !(array2[3].ToUpperInvariant() == "LISTENING"))
							{
								continue;
							}
							string text3 = array2[1];
							string text4 = array2[4];
							string text5 = "Неизвестный процесс";
							int result;
							if (int.TryParse(text4, out result))
							{
								try
								{
									using (Process process2 = Process.GetProcessById(result))
									{
										text5 = process2.ProcessName;
									}
								}
								catch
								{
								}
							}
							string text6 = text5.ToLowerInvariant();
							if (!text3.Contains("127.0.0.1:") && !text3.Contains("0.0.0.0:"))
							{
								continue;
							}
							string s = text3.Substring(text3.LastIndexOf(':') + 1);
							int result2;
							int.TryParse(s, out result2);
							switch (result2)
							{
							case 7890:
							case 7891:
							case 7897:
							case 10808:
							case 10809:
								list.Add(string.Format("\ud83d\udea8 [Localhost Proxy Port] Активен локальный прокси-порт: {0} ({1}, PID: {2})", text3, text5, text4));
								continue;
							case 3240:
								if (text6.Contains("usbipd"))
								{
									list.Add(string.Format("⚠\ufe0f [USBIP Server Port] Активен сервер виртуализации USB-устройств: {0} (usbipd, PID: {1})", text3, text4));
									continue;
								}
								break;
							}
							if (text6.Contains("python") || text6.Contains("node") || text6.Contains("javaw"))
							{
								list.Add(string.Format("⚠\ufe0f [Script/Java Listening Port] Процесс {0} слушает входящий порт {1} (PID: {2})", text5, text3, text4));
							}
						}
					}
				}
			}
			catch
			{
			}
			list = list.Distinct().ToList();
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Сетевая криминалистика", "Аудит прослушиваемых TCP-портов и сокетов (netstat / Listening)", list, flag ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "Подозрительных локальных прокси-портов (7890/7897/10808) или скриптовых сокетов прослушивания не обнаружено"));
			return list2;
		}

