		public static List<CheckResult> RunDefenderThreatDetectionsAndRealtimeTamperingCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			try
			{
				ProcessStartInfo processStartInfo = new ProcessStartInfo("wevtutil.exe", "qe \"Microsoft-Windows-Windows Defender/Operational\" \"/q:*[System[(EventID=1116 or EventID=1117 or EventID=5001 or EventID=5007)]]\" /c:20 /rd:true /f:text");
				processStartInfo.UseShellExecute = false;
				processStartInfo.RedirectStandardOutput = true;
				processStartInfo.CreateNoWindow = true;
				processStartInfo.StandardOutputEncoding = Encoding.GetEncoding(866);
				ProcessStartInfo startInfo = processStartInfo;
				using (Process process = Process.Start(startInfo))
				{
					if (process != null)
					{
						string text = process.StandardOutput.ReadToEnd();
						process.WaitForExit(3000);
						string[] array = text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
						string text2 = "";
						string text3 = "";
						StringBuilder stringBuilder = new StringBuilder();
						bool flag = false;
						for (int i = 0; i < array.Length; i++)
						{
							string text4 = array[i].Trim();
							if (text4.StartsWith("Event ID:"))
							{
								text2 = text4.Substring("Event ID:".Length).Trim();
							}
							else if (text4.StartsWith("Date:"))
							{
								text3 = text4.Substring("Date:".Length).Trim();
							}
							else if (text4.StartsWith("Description:"))
							{
								flag = true;
								stringBuilder.Clear();
							}
							else if (text4.StartsWith("Event[") || i == array.Length - 1)
							{
								DateTime result;
								if (!string.IsNullOrEmpty(text2) && !string.IsNullOrEmpty(text3) && DateTime.TryParse(text3, out result))
								{
									TimeSpan timeSpan = DateTime.UtcNow - result.ToUniversalTime();
									if (timeSpan.TotalDays <= 14.0)
									{
										string text5 = stringBuilder.ToString();
										switch (text2)
										{
										case "1116":
										case "1117":
											string lower5 = text5.ToLowerInvariant();
											bool isMcCheat = lower5.Contains("vape") || lower5.Contains("drip") || lower5.Contains("celestial") ||
															 lower5.Contains("expensive") || lower5.Contains("nursultan") || lower5.Contains("neverhook") ||
															 lower5.Contains("meteor") || lower5.Contains("liquidbounce") || lower5.Contains("wurst") ||
															 lower5.Contains("killaura") || lower5.Contains("akrien") || lower5.Contains("deadcode") ||
															 lower5.Contains("zamorozka") || lower5.Contains("gamehack");
											if (isMcCheat)
											{
												list.Add(string.Format("🚨 [Defender Cheat Detected | {0:dd.MM.yyyy HH:mm}] Зафиксировано обнаружение чита Защитником Windows: {1}", result.ToLocalTime(), (text5.Length > 120) ? (text5.Substring(0, 120) + "...") : text5));
											}
											else
											{
												list.Add(string.Format("ℹ️ [Defender Event {0} | {1:dd.MM.yyyy HH:mm}] Обнаружение стороннего ПО: {2}", text2, result.ToLocalTime(), (text5.Length > 120) ? (text5.Substring(0, 120) + "...") : text5));
											}
											break;
										case "5001":
											list.Add(string.Format("\ud83d\udea8 [Defender Realtime Protection Disabled | {0:dd.MM.yyyy HH:mm}] Защита в реальном времени Defender была отключена пользователем ({1:F1} ч назад)", result.ToLocalTime(), timeSpan.TotalHours));
											break;
										case "5007":
											if (text5.ToLowerInvariant().Contains("exclusion") || text5.ToLowerInvariant().Contains("исключен"))
											{
												list.Add(string.Format("⚠\ufe0f [Defender Exclusion Added | {0:dd.MM.yyyy HH:mm}] Добавлено исключение в параметры Защитника Windows: {1}", result.ToLocalTime(), (text5.Length > 120) ? (text5.Substring(0, 120) + "...") : text5));
											}
											break;
										}
									}
								}
								flag = false;
								text2 = "";
								text3 = "";
								stringBuilder.Clear();
							}
							else if (flag)
							{
								stringBuilder.Append(text4).Append(" ");
							}
						}
					}
				}
			}
			catch
			{
			}
			list = list.Distinct().ToList();
			bool flag2 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Безопасность Windows", "Аудит детектов и отключений Защитника (Defender Events 1116/1117/5001)", list, flag2 ? CheckSeverity.Critical : (list.Any((string f) => f.StartsWith("⚠\ufe0f")) ? CheckSeverity.Warning : CheckSeverity.Info), "Фактов отключения защиты в реальном времени или детектов вредоносных утилит за 14 дней не зафиксировано"));
			return list2;
		}

