		public static List<CheckResult> RunArpCacheAndLocalGatewayCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			try
			{
				ProcessStartInfo processStartInfo = new ProcessStartInfo("arp", "-a");
				processStartInfo.RedirectStandardOutput = true;
				processStartInfo.UseShellExecute = false;
				processStartInfo.CreateNoWindow = true;
				ProcessStartInfo startInfo = processStartInfo;
				using (Process process = Process.Start(startInfo))
				{
					if (process != null)
					{
						string text = process.StandardOutput.ReadToEnd();
						process.WaitForExit(3000);
						string[] array = text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
						string text2 = "Неизвестный интерфейс";
						Dictionary<string, List<string>> dictionary = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
						List<string> list2 = new List<string>();
						string[] array2 = array;
						foreach (string text3 in array2)
						{
							string text4 = text3.Trim();
							if (string.IsNullOrEmpty(text4))
							{
								continue;
							}
							if (text4.IndexOf("Интерфейс", StringComparison.OrdinalIgnoreCase) >= 0 || text4.IndexOf("Interface", StringComparison.OrdinalIgnoreCase) >= 0)
							{
								text2 = text4;
								if (text4.Contains("26.") || text4.Contains("26.178."))
								{
									list.Add("⚠\ufe0f [Виртуальная сеть] Активен сетевой адаптер Radmin VPN (подсеть 26.x.x.x) — частый канал скрытых прокси и приватных чит-серверов");
								}
								else if (text4.Contains("25."))
								{
									list.Add("⚠\ufe0f [Виртуальная сеть] Активен сетевой адаптер LogMeIn Hamachi (подсеть 25.x.x.x)");
								}
								else if (text4.Contains("100."))
								{
									list.Add("⚠\ufe0f [Виртуальная сеть] Активен VPN-адаптер Tailscale / CGNAT (подсеть 100.x.x.x)");
								}
								continue;
							}
							string[] array3 = Regex.Split(text4, "\\s+");
							if (array3.Length < 3 || !array3[1].Contains("-"))
							{
								continue;
							}
							string text5 = array3[0];
							string text6 = array3[1].ToLowerInvariant();
							string text7 = array3[2];
							if (text6 != "ff-ff-ff-ff-ff-ff" && !text6.StartsWith("01-00-5e") && !text6.StartsWith("33-33-"))
							{
								if (!dictionary.ContainsKey(text6))
								{
									dictionary[text6] = new List<string>();
								}
								dictionary[text6].Add(text5);
								list2.Add(string.Format("  • [{0}] IP: {1} -> MAC: {2} ({3})", text2, text5, text6, text7));
							}
						}
						foreach (KeyValuePair<string, List<string>> item in dictionary)
						{
							if (item.Value.Count > 1)
							{
								list.Add(string.Format("\ud83d\udea8 [ARP Подозрение] Обнаружен дубликат MAC-адреса {0} для нескольких IP ({1}) — возможный признак ARP-спуфинга, подмены шлюза или локального перехватчика пакетов", item.Key, string.Join(", ", item.Value.ToArray())));
							}
						}
						if (list2.Count > 0)
						{
							list.Add(string.Format("ℹ\ufe0f Всего зафиксировано {0} валидных хостов в кэше ARP:", list2.Count));
							for (int j = 0; j < Math.Min(list2.Count, 20); j++)
							{
								list.Add(list2[j]);
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("Ошибка анализа ARP: " + ex.Message);
			}
			list = list.Distinct().ToList();
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			bool flag2 = list.Any((string f) => f.StartsWith("⚠\ufe0f"));
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Сетевая криминалистика", "Анализ ARP-таблицы и локальных шлюзов (дубликаты MAC, Radmin, VPN-туннели)", list, flag ? CheckSeverity.Critical : (flag2 ? CheckSeverity.Warning : CheckSeverity.Info), "Аномалий в таблице ARP и следов ARP-спуфинга не обнаружено"));
			return list3;
		}

