				}
			}
			catch (Exception ex2)
			{
				list.Add("Ошибка аудита уведомлений: " + ex2.Message);
			}
			list = list.Distinct().ToList();
			bool flag2 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			bool flag3 = list.Any((string f) => f.StartsWith("⚠\ufe0f"));
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Центр уведомлений", "Форензика центра уведомлений Windows (wpndatabase.db / Toast кэш)", list, flag2 ? CheckSeverity.Critical : (flag3 ? CheckSeverity.Warning : CheckSeverity.Info), "Подозрительных или вредоносных уведомлений в кэше Action Center не обнаружено"));
			return list3;
