		public static List<CheckResult> RunCrashDumpsForensicsCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			try
			{
				string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
				if (!string.IsNullOrEmpty(folderPath))
				{
					string path = Path.Combine(folderPath, "CrashDumps");
					if (Directory.Exists(path))
					{
						string[] files = Directory.GetFiles(path, "*.dmp");
						string[] array = files;
						foreach (string fileName in array)
						{
							try
							{
								FileInfo fileInfo = new FileInfo(fileName);
								string name = fileInfo.Name;
								string text = name.ToLowerInvariant();
								double num = (double)fileInfo.Length / 1048576.0;
								DateTime lastWriteTime = fileInfo.LastWriteTime;
								bool flag = text.StartsWith("javaw.exe") || text.StartsWith("java.exe");
								bool flag2 = false;
								string[] extraCheatClients = CheatDatabases.ExtraCheatClients;
								foreach (string text2 in extraCheatClients)
								{
									if (text2.Length >= 4 && text.Contains(text2.ToLowerInvariant()))
									{
										list.Add(string.Format("\ud83d\udea8 [Крэш-дамп чита: {0}] Обнаружен аварийный дамп чита: \"{1}\" ({2:F1} МБ, от {3:dd.MM.yyyy HH:mm:ss})", text2, name, num, lastWriteTime));
										flag2 = true;
										break;
									}
								}
								if (flag2)
								{
									continue;
								}
								if (flag)
								{
									if (DateTime.Now.Subtract(lastWriteTime).TotalHours <= 72.0)
									{
										list.Add(string.Format("⚠\ufe0f [Крэш-дамп Java (Свежий)] Зафиксирован недавний сбой javaw.exe: \"{0}\" ({1:F1} МБ, от {2:dd.MM.yyyy HH:mm:ss}) — возможный сбой при инжекте", name, num, lastWriteTime));
									}
									else
									{
										list.Add(string.Format("ℹ\ufe0f [Крэш-дамп Java] Зафиксирован архивный сбой javaw.exe: \"{0}\" ({1:F1} МБ, от {2:dd.MM.yyyy HH:mm:ss})", name, num, lastWriteTime));
									}
								}
								else if (text.Contains("cheat") || text.Contains("inject") || text.Contains("vape") || text.Contains("celestial") || text.Contains("expensive"))
								{
									list.Add(string.Format("\ud83d\udea8 [Подозрительный дамп] Обнаружен подозрительный файл крэша: \"{0}\" ({1:F1} МБ, от {2:dd.MM.yyyy HH:mm:ss})", name, num, lastWriteTime));
								}
							}
							catch
							{
							}
						}
					}
				}
				using (RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Microsoft\\Windows\\Windows Error Reporting\\LocalDumps"))
				{
					if (registryKey != null)
					{
						string[] subKeyNames = registryKey.GetSubKeyNames();
						string[] array2 = subKeyNames;
						foreach (string text3 in array2)
						{
							list.Add(string.Format("ℹ\ufe0f [Реестр LocalDumps] Настроена персональная генерация дампов для: {0}", text3));
							using (RegistryKey registryKey2 = registryKey.OpenSubKey(text3))
							{
								if (registryKey2 != null)
								{
									object value = registryKey2.GetValue("DumpType");
									object value2 = registryKey2.GetValue("DumpFolder");
									if (value2 != null)
									{
										list.Add(string.Format("    Кастомная папка дампов: {0} (Тип={1})", value2, value));
									}
								}
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("Ошибка аудита CrashDumps: " + ex.Message);
			}
			list = list.Distinct().ToList();
			bool flag3 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			bool flag4 = list.Any((string f) => f.StartsWith("⚠\ufe0f"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Дампы памяти", "Анализ аварийных дампов памяти (%LOCALAPPDATA%\\CrashDumps / LocalDumps)", list, flag3 ? CheckSeverity.Critical : (flag4 ? CheckSeverity.Warning : CheckSeverity.Info), "Подозрительных дампов сбоев памяти javaw.exe или инжекторов не обнаружено"));
			return list2;
		}

