		private static int FindNbtByte(byte[] data, string name)
		{
			if (data == null || string.IsNullOrEmpty(name))
			{
				return -1;
			}
			byte[] array = new byte[3 + name.Length];
			array[0] = 1;
			array[1] = (byte)((name.Length >> 8) & 0xFF);
			array[2] = (byte)(name.Length & 0xFF);
			for (int i = 0; i < name.Length; i++)
			{
				array[3 + i] = (byte)name[i];
			}
			int num = IndexOfByteArray(data, array);
			if (num != -1 && num + array.Length < data.Length)
			{
				return data[num + array.Length];
			}
			return -1;
		}

		private static int FindNbtInt(byte[] data, string name)
		{
			if (data == null || string.IsNullOrEmpty(name))
			{
				return -1;
			}
			byte[] array = new byte[3 + name.Length];
			array[0] = 3;
			array[1] = (byte)((name.Length >> 8) & 0xFF);
			array[2] = (byte)(name.Length & 0xFF);
			for (int i = 0; i < name.Length; i++)
			{
				array[3 + i] = (byte)name[i];
			}
			int num = IndexOfByteArray(data, array);
			if (num != -1 && num + array.Length + 4 <= data.Length)
			{
				int num2 = num + array.Length;
				return (data[num2] << 24) | (data[num2 + 1] << 16) | (data[num2 + 2] << 8) | data[num2 + 3];
			}
			return -1;
		}

		private static int IndexOfByteArray(byte[] array, byte[] pattern)
		{
			if (array == null || pattern == null || array.Length < pattern.Length)
			{
				return -1;
			}
			for (int i = 0; i <= array.Length - pattern.Length; i++)
			{
				bool flag = true;
				for (int j = 0; j < pattern.Length; j++)
				{
					if (array[i + j] != pattern[j])
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					return i;
				}
			}
			return -1;
		}

		public static List<CheckResult> RunIconAndThumbnailCacheForensicsCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			try
			{
				string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
				if (string.IsNullOrEmpty(folderPath))
				{
					return new List<CheckResult>();
				}
				string text = Path.Combine(folderPath, "IconCache.db");
				if (File.Exists(text))
				{
					FileInfo fileInfo = new FileInfo(text);
					DateTime lastWriteTime = fileInfo.LastWriteTime;
					double totalHours = DateTime.Now.Subtract(lastWriteTime).TotalHours;
					if (totalHours <= 2.0)
					{
						list.Add(string.Format("⚠\ufe0f [IconCache Свежая модификация] База иконок IconCache.db обновлена/пересоздана {0:F1} ч назад ({1:dd.MM.yyyy HH:mm:ss}) — возможная зачистка иконок читов перед проверкой!", totalHours, lastWriteTime));
					}
					else
					{
						list.Add(string.Format("ℹ\ufe0f [IconCache.db] Размер: {0:F1} КБ, последнее обновление: {1:dd.MM.yyyy HH:mm}", (double)fileInfo.Length / 1024.0, lastWriteTime));
					}
				}
				else
				{
					list.Add("\ud83d\udea8 [IconCache.db Удалён] Файл IconCache.db отсутствует в AppData\\Local — характерный признак работы скрипта самоликвидации (ie4uinit.exe -show)!");
				}
				string path = Path.Combine(folderPath, "Microsoft\\Windows\\Explorer");
				if (Directory.Exists(path))
				{
					string[] files = Directory.GetFiles(path, "thumbcache_*.db");
					int num = 0;
					DateTime dateTime = DateTime.MinValue;
					string[] array = files;
					foreach (string fileName in array)
					{
						try
						{
							FileInfo fileInfo2 = new FileInfo(fileName);
							if (fileInfo2.LastWriteTime > dateTime)
							{
								dateTime = fileInfo2.LastWriteTime;
							}
							if (DateTime.Now.Subtract(fileInfo2.LastWriteTime).TotalHours <= 2.0)
							{
								num++;
							}
						}
						catch
						{
						}
					}
					if (files.Length > 0)
					{
						list.Add(string.Format("ℹ\ufe0f [ThumbCache] Найдено {0} файлов кэша миниатюр Explorer (самый свежий: {1:dd.MM.yyyy HH:mm})", files.Length, dateTime));
					}
					else
					{
						list.Add("⚠\ufe0f [ThumbCache Пуст] Файлы кэша миниатюр thumbcache_*.db отсутствуют — признак очистки проводника перед проверкой!");
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("Ошибка проверки кэша иконок: " + ex.Message);
			}
			list = list.Distinct().ToList();
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			bool flag2 = list.Any((string f) => f.StartsWith("⚠\ufe0f"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Кэш иконок и миниатюр", "Форензика IconCache.db и thumbcache_*.db (детект зачистки иконок читов)", list, flag ? CheckSeverity.Critical : (flag2 ? CheckSeverity.Warning : CheckSeverity.Info), "Кэш иконок и миниатюр проводника целостен, признаков недавней зачистки не обнаружено"));
			return list2;
		}

