						{
						}
					}
				}
				if (num > 0 && list.Count == 0)
				{
					list.Add(string.Format("ℹ\ufe0f В очереди ReportQueue проверено {0} ожидающих отчётов (все стандартны)", num));
				}
			}
			catch (Exception ex)
			{
				list.Add("Ошибка анализа ReportQueue: " + ex.Message);
			}
			list = list.Distinct().ToList();
			bool flag2 = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			bool flag3 = list.Any((string f) => f.StartsWith("⚠\ufe0f"));
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Очередь сбоев WER", "Аудит очереди отчётов об ошибках ReportQueue (Report.wer / неотправленные сбои)", list, flag2 ? CheckSeverity.Critical : (flag3 ? CheckSeverity.Warning : CheckSeverity.Info), "Неотправленных сбоев javaw.exe или чит-модулей в очереди ReportQueue не обнаружено"));
			return list3;
		}

		public static List<CheckResult> RunSchannelAndCertificateRevocationTamperingCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			try
			{
				using (RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings"))
				{
					if (registryKey != null)
					{
						object value = registryKey.GetValue("CertificateRevocation");
						if (value != null && value.ToString() == "0")
						{
							list.Add("\ud83d\udea8 [Отключена проверка сертификатов] Параметр CertificateRevocation = 0 — отключена проверка отзыва SSL/TLS сертификатов (характерно для MitM-прокси перехвата игры)!");
						}
						object value2 = registryKey.GetValue("WarnonBadCertRecving");
						if (value2 != null && value2.ToString() == "0")
						{
							list.Add("\ud83d\udea8 [Отключены предупреждения SSL] Параметр WarnonBadCertRecving = 0 — отключены системные предупреждения о недействительных SSL сертификатах!");
						}
					}
				}
				using (RegistryKey registryKey2 = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Policies\\Microsoft\\Windows\\CurrentVersion\\Internet Settings"))
				{
					if (registryKey2 != null)
					{
						object value3 = registryKey2.GetValue("CertificateRevocation");
						if (value3 != null && value3.ToString() == "0")
						{
							list.Add("\ud83d\udea8 [Политика: Отключен отзыв сертификатов] Политика CertificateRevocation = 0 на уровне машины!");
						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("Ошибка проверки Schannel: " + ex.Message);
			}
			list = list.Distinct().ToList();
			bool flag = list.Any((string f) => f.StartsWith("\ud83d\udea8"));
			bool flag2 = list.Any((string f) => f.StartsWith("⚠\ufe0f"));
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Параметры TLS/Schannel", "Аудит целостности проверки сертификатов и TLS-конфигурации (CertificateRevocation)", list, flag ? CheckSeverity.Critical : (flag2 ? CheckSeverity.Warning : CheckSeverity.Info), "Проверка отзыва сертификатов (CRL/OCSP) и параметры безопасности TLS активны"));
			return list2;
		}

