							{
								text2 = " Cmd: " + item["CommandLineTemplate"].ToString();
							}
							if (item["ScriptText"] != null)
							{
								text2 = " ScriptText: " + item["ScriptText"].ToString();
							}
							string text3 = (text + " " + className + " " + text2).ToLowerInvariant();
							bool flag3 = text3.Contains("temp") || text3.Contains("powershell") || text3.Contains("-enc") || text3.Contains(".vbs") || text3.Contains("wscript") || text3.Contains("cmd.exe /c") || text3.Contains("vape") || text3.Contains("cheat") || text3.Contains("cleaner");
