							{
								flag2 = true;
								list.Add(string.Format("⚠\ufe0f [Сторонний WMI Consumer] Класс: {0}, Имя: '{1}'{2}", className, text, text2));
							}
							else
							{
								list.Add(string.Format("ℹ\ufe0f [Штатный WMI Consumer] Класс: {0}, Имя: '{1}'", className, text));
							}
						}
						if (num == 0)
						{
							list.Add("ℹ\ufe0f Активных WMI Event Consumers в root\\subscription не обнаружено.");
						}
					}
				}
