			{
				using (RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Policies\\Microsoft\\Windows Defender"))
				{
					if (registryKey != null)
					{
						object value = registryKey.GetValue("DisableAntiSpyware");
						if (value != null && (value.ToString() == "1" || value.ToString() == "True"))
						{
							flag2 = true;
							list.Add("⚠️ [5.08 - WINDOWS DEFENDER ОТКЛЮЧЕН ПОЛИТИКОЙ] DisableAntiSpyware = 1");
						}
