							{
								string[] polNames = new string[] { "DisableRealtimeMonitoring", "DisableBehaviorMonitoring", "DisableIOAVProtection", "DisableOnAccessProtection", "DisableScanOnRealtimeEnable" };
								foreach (string pol in polNames)
								{
									object val = registryKey2.GetValue(pol);
