			}
			catch
			{
			}
			string[] array = new string[]
			{
				"SOFTWARE\\Policies\\Microsoft\\Windows Defender\\Policy Manager",
				"SOFTWARE\\Microsoft\\Windows Defender\\Exclusions\\Paths",
				"SOFTWARE\\Microsoft\\Windows Defender\\Exclusions\\Processes",
				"SOFTWARE\\Microsoft\\Windows Defender\\Exclusions\\Extensions",
				"SOFTWARE\\Microsoft\\Windows Defender\\Exclusions\\TemporaryPaths"
			};
			string[] array2 = array;
			foreach (string text in array2)
			{
				try
				{
					using (RegistryKey registryKey3 = Registry.LocalMachine.OpenSubKey(text))
					{
						if (registryKey3 == null)
						{
							continue;
						}
						string[] valueNames = registryKey3.GetValueNames();
						string[] array3 = valueNames;
						foreach (string text2 in array3)
						{
							string text3 = text2.ToLowerInvariant();
							bool isExplicitCheatExclusion = text3.Contains("vape") || text3.Contains("celestial") || text3.Contains("expensive") || text3.Contains("nursultan") || text3.Contains("wexside") || text3.Contains("killaura") || text3.Contains("cheatloader");
							if (isExplicitCheatExclusion)
							{
								flag = true;
								list.Add(string.Format("🚨 [5.08 - ИСКЛЮЧЕНИЕ ЧИТА В DEFENDER] {0} -> '{1}'", text, text2));
							}
							else
							{
								list.Add(string.Format("ℹ️ [Исключение Defender] {0} -> '{1}'", text, text2));
							}
						}
					}
				}
				catch
				{
				}
			}
			try
			{
				string query = "*[System[(EventID=1116 or EventID=1117 or EventID=1006 or EventID=1007 or EventID=5007)]]";
				EventLogQuery eventLogQuery = new EventLogQuery("Microsoft-Windows-Windows Defender/Operational", PathType.LogName, query);
				eventLogQuery.ReverseDirection = true;
				using (EventLogReader eventLogReader = new EventLogReader(eventLogQuery))
				{
					int countDetections = 0;
					int countConfigs = 0;
					EventRecord eventRecord;
					while ((eventRecord = eventLogReader.ReadEvent()) != null && (countDetections < 15 || countConfigs < 3))
					{
						using (eventRecord)
						{
							int id = eventRecord.Id;
							string desc = (eventRecord.FormatDescription() ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
							string dt = (eventRecord.TimeCreated.HasValue ? eventRecord.TimeCreated.Value.ToString("dd.MM.yyyy HH:mm") : "");
							TimeSpan age = eventRecord.TimeCreated.HasValue ? (DateTime.Now - eventRecord.TimeCreated.Value) : TimeSpan.FromDays(999);

							if (id == 1116 || id == 1117 || id == 1006 || id == 1007)
							{
								if (age.TotalDays <= 30.0 && countDetections < 15)
								{
									countDetections++;
									string descLower = desc.ToLowerInvariant();
									bool isCheatThreat = descLower.Contains("gamehack") || descLower.Contains("vape") || descLower.Contains("celestial") ||
										descLower.Contains("expensive") || descLower.Contains("nursultan") || descLower.Contains("wexside") ||
										descLower.Contains("killaura") || descLower.Contains("cheatloader") || descLower.Contains("hacktool:win32/vape") ||
										descLower.Contains("hacktool:java/celestial");

									if (desc.Length > 200)
									{
										desc = desc.Substring(0, 200) + "...";
									}

									if (isCheatThreat)
									{
										flag = true;
										if (id == 1117 || id == 1007)
										{
											list.Add(string.Format("🗑️ [5.08 - ЧИТ УДАЛЁН DEFENDER ({0})] {1}", dt, desc));
										}
										else
										{
											list.Add(string.Format("🚨 [5.01 - ОБНАРУЖЕНИЕ ЧИТА DEFENDER ({0})] {1}", dt, desc));
										}
									}
									else
									{
										list.Add(string.Format("ℹ️ [Детект сторонних программ Defender ({0})] {1}", dt, desc));
									}
								}
							}
							else if (id == 5007 && countConfigs < 3)
							{
								countConfigs++;
								if (desc.Length > 150)
								{
									desc = desc.Substring(0, 150) + "...";
								}
								list.Add(string.Format("ℹ️ [Изменение конфигурации Defender ({0})] {1}", dt, desc));
							}
						}
					}
				}
			}
			catch
			{
			}
