		public static List<CheckResult> RunJavawNetworkConnectionsDeepAuditCheck()
		{
			List<string> list = new List<string>();
			if (!PlatformHelper.IsWindows)
			{
				return new List<CheckResult>();
			}
			bool flag = false;
			bool flag2 = false;
			try
			{
				Process[] processesByName = Process.GetProcessesByName("javaw");
				List<int> list2 = new List<int>();
				Process[] array = processesByName;
				foreach (Process process in array)
				{
					list2.Add(process.Id);
				}
				Process[] processesByName2 = Process.GetProcessesByName("java");
				Process[] array2 = processesByName2;
				foreach (Process process2 in array2)
				{
					list2.Add(process2.Id);
				}
				if (list2.Count == 0)
				{
					list.Add("ℹ\ufe0f Процесс javaw.exe / java.exe в данный момент не запущен.");
				}
				else
				{
					list.Add(string.Format("ℹ\ufe0f Обнаружено {0} активных процессов Java (PIDs: {1})", list2.Count, string.Join(", ", list2.ConvertAll((int x) => x.ToString()).ToArray())));
				}
				ProcessStartInfo processStartInfo = new ProcessStartInfo("netstat", "-ano -p tcp");
				processStartInfo.UseShellExecute = false;
				processStartInfo.RedirectStandardOutput = true;
				processStartInfo.RedirectStandardError = true;
				processStartInfo.CreateNoWindow = true;
				ProcessStartInfo startInfo = processStartInfo;
				using (Process process3 = Process.Start(startInfo))
				{
					string text = process3.StandardOutput.ReadToEnd();
					process3.WaitForExit(3000);
					if (!string.IsNullOrEmpty(text))
					{
						string[] array3 = text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
						int num = 0;
						string[] array4 = array3;
						foreach (string text2 in array4)
						{
							string text3 = text2.Trim();
							if (!text3.StartsWith("TCP", StringComparison.OrdinalIgnoreCase))
							{
								continue;
							}
							string[] array5 = text3.Split(new char[1] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
							if (array5.Length < 5)
							{
								continue;
							}
							string text4 = array5[1];
							string text5 = array5[2];
							string text6 = array5[3];
							string s = array5[4];
							int result;
							if (int.TryParse(s, out result) && list2.Contains(result))
							{
								num++;
								if ((text5.StartsWith("127.0.0.1:") || text5.StartsWith("[::1]:")) && text6.Equals("ESTABLISHED", StringComparison.OrdinalIgnoreCase))
								{
									flag = true;
									list.Add(string.Format("\ud83d\udea8 [ЛОКАЛЬНОЕ СОЕДИНЕНИЕ JAVAW (MITM ПРОКСИ)] PID {0} -> Local: {1}, Remote: {2} ({3})", result, text4, text5, text6));
								}
								else
								{
									list.Add(string.Format("ℹ\ufe0f [Сетевой сокет javaw.exe] PID {0} -> Local: {1}, Remote: {2} ({3})", result, text4, text5, text6));
								}
							}
						}
						if (list2.Count > 0 && num == 0)
						{
							list.Add("ℹ\ufe0f Активных внешних TCP-соединений у запущенных процессов javaw.exe не зафиксировано (одиночная игра или меню).");
						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("⚠\ufe0f Ошибка аудита сокетов netstat: " + ex.Message);
			}
			List<CheckResult> list3 = new List<CheckResult>();
			list3.Add(Make("Сетевые соединения Minecraft (javaw.exe)", "Аудит активных сетевых TCP-сокетов процесса javaw.exe (netstat / сокеты)", list, flag ? CheckSeverity.Critical : (flag2 ? CheckSeverity.Warning : CheckSeverity.Info), flag ? "ОБНАРУЖЕНО ЛОКАЛЬНОЕ ПОДКЛЮЧЕНИЕ JAVAW К LOOPBACK ПРОКСИ (127.0.0.1)!" : "Сетевые соединения процесса javaw.exe в норме"));
			return list3;
		}

