			}
			string[] valueNames = key.GetValueNames();
			if (valueNames != null)
			{
				string[] array = valueNames;
				foreach (string text in array)
				{
					if (text == "MRUListEx")
					{
						continue;
					}
					count++;
					try
					{
						object value = key.GetValue(text);
						byte[] array2 = value as byte[];
						if (array2 == null || array2.Length <= 4)
						{
							continue;
						}
						string text2 = Encoding.ASCII.GetString(array2);
						string text3 = Encoding.Unicode.GetString(array2);
						string text4 = (text2 + " " + text3).ToLowerInvariant();
						foreach (string text5 in signatures)
						{
							if (!text4.Contains(text5))
							{
								continue;
							}
							bool flag = true;
							if (text5 == "b13" && text4.Contains("version-"))
							{
								flag = false;
							}
							if (flag)
							{
								string item = string.Format("\ud83d\udea8 [ShellBags / Папка чита] В истории открытия папок Windows обнаружен каталог '{0}' (Ветка: {1})", text5.ToUpperInvariant(), (currentPath.Length > 0) ? currentPath : "Корень");
								if (!found.Contains(item))
								{
									found.Add(item);
								}
								break;
							}
						}
					}
					catch
					{
					}
				}
			}
			string[] subKeyNames = key.GetSubKeyNames();
			if (subKeyNames == null)
			{
				return;
			}
			string[] array3 = subKeyNames;
			foreach (string text6 in array3)
			{
				try
				{
					using (RegistryKey registryKey = key.OpenSubKey(text6))
					{
						if (registryKey != null)
						{
							WalkBagMruSubTree(registryKey, currentPath + "/" + text6, ref count, signatures, found);
						}
					}
				}
				catch
				{
				}
			}
		}

