						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("⚠️ Ошибка аудита базы уведомлений: " + ex.Message);
			}
			CheckSeverity severity = CheckSeverity.Info;
			if (list.Any((string f) => f.Contains("\ud83d\udea8")))
			{
				severity = CheckSeverity.Critical;
			}
			else if (list.Count > 0)
			{
				severity = CheckSeverity.Warning;
			}
			List<CheckResult> list4 = new List<CheckResult>();
			list4.Add(Make("Система / Notification Forensics", "Криминалистика базы уведомлений Windows (wpndatabase.db)", list, severity, string.Format("База данных всплывающих уведомлений Windows проверена (размер: {0:N0} КБ). Следов уведомлений инжекции и покупки читов не обнаружено.", new FileInfo(text).Length / 1024)));
			return list4;
		}

