		private static long ExtractJsonMetric(string json, string metricKey)
		{
			if (string.IsNullOrEmpty(json) || string.IsNullOrEmpty(metricKey))
			{
				return 0L;
			}
			try
			{
				int num = json.IndexOf("\"" + metricKey + "\"", StringComparison.OrdinalIgnoreCase);
				if (num < 0)
				{
					num = json.IndexOf("minecraft:" + metricKey + "\"", StringComparison.OrdinalIgnoreCase);
				}
				if (num < 0)
				{
					return 0L;
				}
				int num2 = json.IndexOf(':', num + metricKey.Length);
				if (num2 < 0)
				{
					return 0L;
				}
				int i;
				for (i = num2 + 1; i < json.Length && (json[i] == ' ' || json[i] == '\t' || json[i] == '\r' || json[i] == '\n'); i++)
				{
				}
				int j;
				for (j = i; j < json.Length && (char.IsDigit(json[j]) || json[j] == '-'); j++)
				{
				}
				if (j > i)
				{
					string s = json.Substring(i, j - i);
					long result;
					if (long.TryParse(s, out result))
					{
						return result;
					}
				}
			}
			catch
			{
			}
			return 0L;
		}

