		private static void CheckBagMruRecursive(RegistryKey key, string currentPath, string[] cheatNames, List<string> found, int depth)
		{
			if (key == null || depth > 6)
			{
				return;
			}
			try
			{
				string[] valueNames = key.GetValueNames();
				string[] array = valueNames;
				foreach (string text in array)
				{
					if (!(text != "MRUListEx") || !(text != "NodeSlot"))
					{
						continue;
					}
					byte[] array2 = key.GetValue(text) as byte[];
					if (array2 == null || array2.Length <= 10)
					{
						continue;
					}
					string text2 = Encoding.ASCII.GetString(array2).ToLowerInvariant();
					foreach (string text3 in cheatNames)
					{
						if (text2.Contains(text3))
						{
							found.Add(string.Format("[SHELLBAGS ПАПКА ЧИТА] Обнаружен узел каталога с упоминанием '{0}' в BagMRU", text3));
							break;
						}
					}
				}
				string[] subKeyNames = key.GetSubKeyNames();
				string[] array3 = subKeyNames;
				foreach (string text4 in array3)
				{
					using (RegistryKey key2 = key.OpenSubKey(text4))
					{
						CheckBagMruRecursive(key2, currentPath + "/" + text4, cheatNames, found, depth + 1);
					}
				}
			}
			catch
			{
			}
		}

