			stringBuilder.AppendLine("  .meta-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 13px; color: #a0a0b2; }");
			stringBuilder.AppendLine("  .meta-grid strong { color: #ffffff; }");
