			stringBuilder.AppendLine("  .card-detail { font-size: 13px; color: #b0b0c2; margin-bottom: 8px; }");
			stringBuilder.AppendLine("  details { margin-top: 8px; background: #0e0f13; border: 1px solid #262738; border-radius: 6px; padding: 8px 12px; }");
