			stringBuilder.AppendLine("  .copy-btn:hover { background: #00bfa5; color: #000; }");
			stringBuilder.AppendLine("  pre { font-family: 'Consolas', 'Courier New', monospace; font-size: 11px; color: #cfd8dc; white-space: pre-wrap; word-break: break-all; padding: 6px; overflow-x: auto; }");
			stringBuilder.AppendLine("  .footer { text-align: center; font-size: 12px; color: #5a5a70; margin-top: 40px; padding: 20px; border-top: 1px solid #222330; }");
			stringBuilder.AppendLine("</style>");
			stringBuilder.AppendLine("</head>");
			stringBuilder.AppendLine("<body>");
			stringBuilder.AppendLine("<div class=\"container\">");
			stringBuilder.AppendLine("  <div class=\"header\">");
			stringBuilder.AppendLine("    <div class=\"brand\">");
			stringBuilder.AppendLine("      <h1>MC CHEAT CHECKER • КРИМИНАЛИСТИЧЕСКИЙ ОТЧЁТ SCREENSHARE</h1>");
			stringBuilder.AppendLine("      <span class=\"tag\">ATLANTIS SS EDITION</span>");
			stringBuilder.AppendLine("    </div>");
			stringBuilder.AppendLine("    <div class=\"meta-grid\">");
			stringBuilder.AppendLine(string.Format("      <div><strong>Дата и время:</strong> {0:dd.MM.yyyy HH:mm:ss}</div>", DateTime.Now));
			stringBuilder.AppendLine(string.Format("      <div><strong>Компьютер:</strong> {0}</div>", HtmlEnc(Environment.MachineName)));
			stringBuilder.AppendLine(string.Format("      <div><strong>Пользователь:</strong> {0}</div>", HtmlEnc(Environment.UserName)));
			stringBuilder.AppendLine(string.Format("      <div><strong>Операционная система:</strong> {0}</div>", HtmlEnc(PlatformHelper.OSDescription)));
			stringBuilder.AppendLine(string.Format("      <div><strong>Аптайм системы:</strong> {0:F1} часов</div>", TimeSpan.FromMilliseconds(Environment.TickCount).TotalHours));
