			stringBuilder.AppendLine(string.Format("    <div class=\"stat-card info\"><div class=\"stat-val\">{0}</div><div class=\"stat-label\">Инфо / Штатно</div></div>", num3));
			stringBuilder.AppendLine(string.Format("    <div class=\"stat-card total\"><div class=\"stat-val\">{0}</div><div class=\"stat-label\">Всего проверок</div></div>", count));
			stringBuilder.AppendLine("  </div>");
