			stringBuilder.AppendLine("</div>");
			stringBuilder.AppendLine("<script>");
			stringBuilder.AppendLine("  let currentSev = 'all';");
			stringBuilder.AppendLine("  function setSeverity(sev, btn) {");
			stringBuilder.AppendLine("    currentSev = sev;");
			stringBuilder.AppendLine("    document.querySelectorAll('.filter-btns .btn').forEach(b => b.classList.remove('active'));");
			stringBuilder.AppendLine("    btn.classList.add('active');");
			stringBuilder.AppendLine("    applyFilter();");
			stringBuilder.AppendLine("  }");
			stringBuilder.AppendLine("  function applyFilter() {");
			stringBuilder.AppendLine("    let q = (document.getElementById('searchBox').value || '').toLowerCase();");
			stringBuilder.AppendLine("    document.querySelectorAll('.card').forEach(card => {");
			stringBuilder.AppendLine("      let sev = card.getAttribute('data-sev');");
			stringBuilder.AppendLine("      let text = card.innerText.toLowerCase();");
			stringBuilder.AppendLine("      let matchSev = (currentSev === 'all' || sev === currentSev);");
			stringBuilder.AppendLine("      let matchQuery = (q === '' || text.indexOf(q) !== -1);");
			stringBuilder.AppendLine("      card.style.display = (matchSev && matchQuery) ? 'block' : 'none';");
			stringBuilder.AppendLine("    });");
			stringBuilder.AppendLine("  }");
			stringBuilder.AppendLine("  function toggleAll(open) {");
			stringBuilder.AppendLine("    document.querySelectorAll('details').forEach(d => d.open = open);");
			stringBuilder.AppendLine("  }");
			stringBuilder.AppendLine("  function copyEvidence(btn) {");
			stringBuilder.AppendLine("    let code = btn.nextElementSibling.innerText;");
			stringBuilder.AppendLine("    navigator.clipboard.writeText(code).then(() => {");
			stringBuilder.AppendLine("      let old = btn.innerText;");
			stringBuilder.AppendLine("      btn.innerText = '✅ Скопировано!';");
			stringBuilder.AppendLine("      setTimeout(() => btn.innerText = old, 1500);");
			stringBuilder.AppendLine("    });");
			stringBuilder.AppendLine("  }");
			stringBuilder.AppendLine("</script>");
			stringBuilder.AppendLine("</body>");
			stringBuilder.AppendLine("</html>");
			string contents = stringBuilder.ToString();
			string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
			string path = string.Format("SS_Report_{0:yyyyMMdd_HHmmss}.html", DateTime.Now);
			string text2 = Path.Combine(folderPath, path);
			File.WriteAllText(text2, contents, Encoding.UTF8);
			return text2;
		}

