		public static List<CheckResult> RunWindowsVolumeShadowCopyDeletionEventsCheck()
		{
			List<string> list = new List<string>();
			int num = 0;
			try
			{
				using (EventLog eventLog = new EventLog("System"))
				{
					int count = eventLog.Entries.Count;
					int num2 = Math.Max(0, count - 2500);
					DateTime dateTime = DateTime.Now.AddHours(-24.0);
					int num3 = count - 1;
					while (num3 >= num2)
					{
						try
						{
							EventLogEntry eventLogEntry = eventLog.Entries[num3];
							if (eventLogEntry.TimeGenerated < dateTime)
							{
								break;
							}
							num++;
							if (eventLogEntry.Source != null && (eventLogEntry.Source.IndexOf("VSS", StringComparison.OrdinalIgnoreCase) >= 0 || eventLogEntry.Source.IndexOf("VolSnap", StringComparison.OrdinalIgnoreCase) >= 0 || eventLogEntry.Source.IndexOf("Service Control Manager", StringComparison.OrdinalIgnoreCase) >= 0))
							{
								string text = eventLogEntry.Message ?? "";
								if (eventLogEntry.InstanceId == 7036 && text.IndexOf("Volume Shadow Copy", StringComparison.OrdinalIgnoreCase) >= 0)
								{
									if (text.IndexOf("остановлена", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("stopped", StringComparison.OrdinalIgnoreCase) >= 0)
									{
										list.Add("[VSS 7036] " + eventLogEntry.TimeGenerated.ToString("yyyy-MM-dd HH:mm:ss") + " | Остановка службы VSS: " + text.Replace("\r", " ").Replace("\n", " "));
									}
								}
								else if (eventLogEntry.InstanceId == 8224 || eventLogEntry.InstanceId == 12289 || eventLogEntry.InstanceId == 12302)
								{
									list.Add("[VSS " + eventLogEntry.InstanceId + "] " + eventLogEntry.TimeGenerated.ToString("yyyy-MM-dd HH:mm:ss") + " | Событие VSS: " + text.Replace("\r", " ").Replace("\n", " "));
								}
							}
							goto IL_021c;
						}
						catch
						{
							goto IL_021c;
						}
						IL_021c:
						if (list.Count < 10)
						{
							num3--;
							continue;
						}
						break;
					}
				}
			}
			catch
			{
			}
			try
			{
				using (RegistryKey registryKey = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\SystemRestore"))
				{
					if (registryKey != null)
					{
						object value = registryKey.GetValue("DisableSR");
						if (value != null && value.ToString() == "1")
						{
							list.Add("[REGISTRY] DisableSR=1 (Создание точек восстановления системы принудительно отключено в реестре)");
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				ProcessStartInfo processStartInfo = new ProcessStartInfo();
				processStartInfo.FileName = "vssadmin.exe";
				processStartInfo.Arguments = "list shadows";
				processStartInfo.UseShellExecute = false;
				processStartInfo.RedirectStandardOutput = true;
				processStartInfo.CreateNoWindow = true;
				using (Process process = Process.Start(processStartInfo))
				{
					string text2 = process.StandardOutput.ReadToEnd();
					process.WaitForExit(3000);
					if (text2.IndexOf("отсутствуют", StringComparison.OrdinalIgnoreCase) >= 0 || text2.IndexOf("No items found", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						list.Add("[VSSADMIN] На текущем системном томе отсутствуют теневые копии (возможно полное удаление через 'vssadmin delete shadows')");
					}
					else if (text2.IndexOf("Contents of shadow copy set", StringComparison.OrdinalIgnoreCase) < 0)
					{
						text2.IndexOf("Содержимое набора теневых копий", StringComparison.OrdinalIgnoreCase);
					}
				}
			}
			catch
			{
			}
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Форензика / VSS & ShadowCopy Deletion", "Аудит удаления теневых копий томов и событий сброса VSS", list, (list.Count > 0 && list.Any((string f) => f.Contains("DisableSR") || f.Contains("отсутствуют"))) ? CheckSeverity.Warning : CheckSeverity.Info, "Удалений теневых копий VSS и аномальных сбросов точек восстановления не зафиксировано (проверено событий: " + num + ")."));
			return list2;
		}

		public static List<CheckResult> RunMinecraftFabricLoaderMixinSyntheticBridgeCheck()
		{
			List<string> list = new List<string>();
			string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
			string path = Path.Combine(folderPath, ".minecraft");
			string path2 = Path.Combine(path, "mods");
			int num = 0;
			string[] array = new string[11]
			{
				"setReach", "getAttackRange", "getBoxForEntity", "isSilentSprint", "sendPacketNoEvent", "cancelPacket", "setHitboxExpansion", "getRawAABB", "overrideStepHeight", "bypassRaycast",
				"suppressKnockback"
			};
			if (Directory.Exists(path2))
			{
				string[] files = Directory.GetFiles(path2, "*.jar", SearchOption.AllDirectories);
				string[] array2 = files;
				foreach (string text in array2)
				{
					num++;
					try
					{
						using (ZipArchive zipArchive = ZipFile.OpenRead(text))
						{
							foreach (ZipArchiveEntry entry in zipArchive.Entries)
							{
								if (entry.Name.EndsWith(".mixins.json", StringComparison.OrdinalIgnoreCase) || entry.Name.EndsWith(".mixin.json", StringComparison.OrdinalIgnoreCase))
								{
									using (Stream stream = entry.Open())
									{
										using (StreamReader streamReader = new StreamReader(stream, Encoding.UTF8))
										{
											string text2 = streamReader.ReadToEnd();
											if (text2.IndexOf("\"priority\"", StringComparison.OrdinalIgnoreCase) >= 0)
											{
												Match match = Regex.Match(text2, "\\\"priority\\\"\\s*:\\s*(-?\\d+)");
												int result;
												if (match.Success && int.TryParse(match.Groups[1].Value, out result) && (result > 5000 || result < -5000))
												{
													list.Add(string.Format("[SUSPICIOUS MIXIN PRIORITY] {0} -> {1} (priority: {2})", Path.GetFileName(text), entry.FullName, result));
												}
											}
											if (text2.IndexOf("\"plugin\"", StringComparison.OrdinalIgnoreCase) >= 0)
