				using (Process process = Process.Start(processStartInfo))
				{
					num++;
					string text = process.StandardOutput.ReadToEnd();
					string text2 = process.StandardError.ReadToEnd();
					process.WaitForExit(3000);
					if (text2.IndexOf("не активен", StringComparison.OrdinalIgnoreCase) >= 0 || text2.IndexOf("not active", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("не активен", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("not active", StringComparison.OrdinalIgnoreCase) >= 0)
