								{
									entry.FullName.EndsWith(".SF", StringComparison.OrdinalIgnoreCase);
								}
								if (entry.Name.Equals("fabric.mod.json", StringComparison.OrdinalIgnoreCase))
								{
									flag = true;
								}
							}
							string text2 = Path.GetFileName(text).ToLowerInvariant();
							if ((text2.Contains("sodium") || text2.Contains("fabric-api") || text2.Contains("iris")) && !flag)
							{
								list.Add(string.Format("[MASQUERADED UTILITY MOD] '{0}' маскируется под официальный мод, но не имеет fabric.mod.json", Path.GetFileName(text)));
