			list2.Add(Make("Minecraft / Mod Integrity & Manifest Check", "Проверка манифестов META-INF и целостности структуры служебных JAR-модов", list, CheckSeverity.Critical, "Целостность манифестов и структуры официальных JAR-модов подтверждена (проверено модов: " + num + ")."));
