					action(arg, "ResourcePack");
					if (found.Count >= 8)
					{
						break;
					}
				}
			}
			if (Directory.Exists(path3))
			{
				string[] files2 = Directory.GetFiles(path3, "*.zip", SearchOption.TopDirectoryOnly);
				foreach (string arg2 in files2)
				{
					action(arg2, "ShaderPack");
					if (found.Count >= 8)
					{
						break;
					}
				}
			}
			List<CheckResult> list = new List<CheckResult>();
			list.Add(Make("Minecraft / Entity Glowing Outline Shaders", "Аудит кастомных шейдеров подсветки сущностей и контуров Glowing ESP сквозь стены", found, CheckSeverity.Critical, "Подозрительных шейдеров подсветки контуров Glowing ESP не обнаружено (проверено файлов: " + scannedFiles + ")."));
			return list;
