		public static List<CheckResult> RunWindowsVolumeShadowCopyDeletionServiceStateChangeCheck()
		{
			List<string> list = new List<string>();
			int num = 0;
			try
			{
				using (EventLog eventLog = new EventLog("System"))
				{
					int count = eventLog.Entries.Count;
					int num2 = Math.Max(0, count - 2500);
					DateTime dateTime = DateTime.Now.AddHours(-48.0);
					int num3 = count - 1;
					while (num3 >= num2)
					{
						try
						{
							EventLogEntry eventLogEntry = eventLog.Entries[num3];
							if (eventLogEntry.TimeGenerated < dateTime)
							{
								break;
							}
							num++;
							if (eventLogEntry.InstanceId == 7040 && eventLogEntry.Source != null && eventLogEntry.Source.IndexOf("Service Control Manager", StringComparison.OrdinalIgnoreCase) >= 0)
							{
								string text = eventLogEntry.Message ?? "";
								if (text.IndexOf("Volume Shadow Copy", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("VSS", StringComparison.OrdinalIgnoreCase) >= 0)
								{
									list.Add(string.Format("[VSS START TYPE ALTERED] {0} | Изменен тип запуска службы VSS (Event 7040): {1}", eventLogEntry.TimeGenerated.ToString("yyyy-MM-dd HH:mm:ss"), text.Replace("\r", " ").Replace("\n", " ")));
								}
							}
							goto IL_0128;
						}
						catch
						{
							goto IL_0128;
						}
						IL_0128:
						if (list.Count < 8)
						{
							num3--;
							continue;
						}
						break;
					}
				}
			}
			catch
			{
			}
			List<CheckResult> list2 = new List<CheckResult>();
			list2.Add(Make("Форензика / VSS Service Start Type Alterations", "Аудит событий изменения типа запуска службы Volume Shadow Copy (Event 7040 — Disabled / Demand)", list, (list.Count > 0) ? CheckSeverity.Warning : CheckSeverity.Info, "Изменений типа запуска службы VSS за последние 48 часов не зафиксировано (проверено событий: " + num + ")."));
			return list2;
		}

